// Tata bahasa + terjemahan Indonesia (otomatis via Google Translate).
export default [{"pattern":"A が いちばん～","meaning":"Express the superlative degree; 'the most', 'the best', 'the least'.","meaningId":"Nyatakan derajat superlatif; 'yang paling', 'yang terbaik', 'yang paling sedikit'.","formation":"Noun + が + いちばん + Adjective/Verb","formationId":"Kata Benda + が + いちばん + Kata Sifat/Kata Kerja","examples":[{"jp":"この中で、寿司が一番好きです。","romaji":"Kono naka de, sushi ga ichiban suki desu.","en":"Of all these, I like sushi the most.","id":"Dari semuanya, saya paling suka sushi."},{"jp":"彼女はクラスで一番速く泳げます。","romaji":"Kanojo wa kurasu de ichiban hayaku oyogemasu.","en":"She can swim the fastest in the class.","id":"Dia bisa berenang paling cepat di kelasnya."},{"jp":"この町では、この公園が一番きれいです。","romaji":"Kono machi de wa, kono kouen ga ichiban kirei desu.","en":"In this town, this park is the most beautiful.","id":"Di kota ini, taman ini adalah yang terindah."},{"jp":"飲み物の中では、紅茶が一番好きです。","romaji":"Nomimono no naka de wa, koucha ga ichiban suki desu.","en":"Among all drinks, I like tea the most.","id":"Di antara semua minuman, saya paling suka teh."}]},{"pattern":"A。けれども、～B。(A. Keredomo,~ B.)","meaning":"Used to express a contrast between two statements. It can be translated as 'but' or 'however'.","meaningId":"Digunakan untuk menyatakan kontras antara dua pernyataan. Ini dapat diterjemahkan sebagai 'tetapi' atau 'namun'.","formation":"Statement A + けれども、+ Statement B","formationId":"Pernyataan A + けれども、+ Pernyataan B","examples":[{"jp":"今日は晴れている。けれども、寒いです。","romaji":"Kyou wa harete iru. Keredo mo, samui desu.","en":"It is sunny today. However, it is cold.","id":"Hari ini cerah. Namun, cuacanya dingin."},{"jp":"彼女はうるさい。けれども、面白いです。","romaji":"Kanojo wa urusai. Keredo mo, omoshiroi desu.","en":"She is noisy. But, she is interesting.","id":"Dia berisik. Tapi, dia menarik."},{"jp":"その映画は長かった。けれども、退屈じゃなかった。","romaji":"Sono eiga wa nagakatta. Keredo mo, taikutsu janakatta.","en":"The movie was long. But, it wasn't boring.","id":"Filmnya panjang. Tapi, itu tidak membosankan."},{"jp":"彼は運動が得意だ。けれども、勉強は苦手だ。","romaji":"Kare wa undou ga tokui da. Keredo mo, benkyou wa nigate da.","en":"He is good at sports. However, he is not good at studying.","id":"Dia pandai olahraga. Namun, dia tidak pandai belajar."}]},{"pattern":"A。しかし、～B。 (A. Shikashi, ~B.)","meaning":"Expresses contrast or contradiction between two clauses; 'A, but B', 'A, however B'.","meaningId":"Menyatakan kontras atau pertentangan antara dua klausa; 'A, tapi B', 'A, bagaimanapun B'.","formation":"Sentence A + しかし + Sentence B.","formationId":"Kalimat A + しかし + Kalimat B.","examples":[{"jp":"今日は忙しい。しかし、時間があるなら、コーヒーを飲もう。","romaji":"Kyou wa isogashii. Shikashi, jikan ga aru nara, koohii o nomou.","en":"I'm busy today. However, if I have time, let's have coffee.","id":"Saya sibuk hari ini. Namun, jika saya punya waktu, mari kita minum kopi."},{"jp":"その映画は面白かった。しかし、長すぎました。","romaji":"Sono eiga wa omoshirokatta. Shikashi, nagasugimashita.","en":"The movie was interesting. But, it was too long.","id":"Filmnya menarik. Tapi, itu terlalu lama."},{"jp":"彼は疲れていた。しかし、宿題を終わらせた。","romaji":"Kare wa tsukareteita. Shikashi, shukudai o owaraseta.","en":"He was tired. However, he finished his homework.","id":"Dia lelah. Namun, dia menyelesaikan pekerjaan rumahnya."},{"jp":"部屋は狭いです。しかし、便利な場所にあります。","romaji":"Heya wa semai desu. Shikashi, benri na basho ni arimasu.","en":"The room is small. But, it is in a convenient location.","id":"Kamarnya kecil. Tapi, letaknya di lokasi yang nyaman."}]},{"pattern":"A。じゃ、～B。(A. Ja, ~B.)","meaning":"Indicates a decision or suggestion; 'well then', 'in that case', 'so'.","meaningId":"Menunjukkan keputusan atau saran; 'kalau begitu', 'kalau begitu', 'jadi'.","formation":"A: Sentence, B: Sentence (A and B can be any sentence type)","formationId":"A: Kalimat, B: Kalimat (A dan B bisa jenis kalimat apa saja)","examples":[{"jp":"映画は時間がない。じゃ、また今度行こう。","romaji":"Eiga wa jikan ga nai. Ja, mata kondo ikou.","en":"There's no time for a movie. Well then, let's go another time.","id":"Tidak ada waktu untuk menonton film. Kalau begitu, ayo kita pergi lagi lain kali."},{"jp":"お腹がすいた。じゃ、レストランに行こう。","romaji":"Onaka ga suita. Ja, resutoran ni ikou.","en":"I'm hungry. In that case, let's go to a restaurant.","id":"saya lapar. Kalau begitu, ayo pergi ke restoran."},{"jp":"電車が遅れた。じゃ、バスで行こう。","romaji":"Densha ga okureta. Ja, basu de ikou.","en":"The train is late. So, let's go by bus.","id":"Keretanya terlambat. Kalau begitu, ayo naik bus."},{"jp":"このシャツは高い。じゃ、別のを買おう。","romaji":"Kono shatsu wa takai. Ja, betsu no o kau.","en":"This shirt is expensive. Well then, let's buy a different one.","id":"Baju ini mahal. Kalau begitu, ayo beli yang lain."}]},{"pattern":"A。それじゃ、～B。(A. Soreja,~B.)","meaning":"Connect two sentences; 'A, so/in that case, B'","meaningId":"Hubungkan dua kalimat; 'A, jadi/kalau begitu, B'","formation":"Sentence A + 。それじゃ、 + Sentence B","formationId":"Kalimat A + 。それじゃ、 + Kalimat B","examples":[{"jp":"今日は休みです。それじゃ、映画を観に行きましょう。","romaji":"Kyou wa yasumi desu. Soreja, eiga wo mi ni ikimashou.","en":"Today is a day off. In that case, let's go watch a movie.","id":"Hari ini adalah hari libur. Kalau begitu, ayo kita menonton film."},{"jp":"電気が切れた。それじゃ、ろうそくを使いましょう。","romaji":"Denki ga kireta. Soreja, rousoku wo tsukaimashou.","en":"The electricity went out. In that case, let's use candles.","id":"Listrik padam. Kalau begitu, ayo gunakan lilin."},{"jp":"レストランが混んでいます。それじゃ、別の場所で食べましょう。","romaji":"Resutoran ga kondeimasu. Soreja, betsu no basho de tabemashou.","en":"The restaurant is crowded. In that case, let's eat somewhere else.","id":"Restorannya ramai. Kalau begitu, ayo makan di tempat lain."},{"jp":"明日は雨が降るらしい。それじゃ、ピクニックは中止しましょう。","romaji":"Ashita wa ame ga furu rashii. Soreja, pikunikku wa chuushi shimashou.","en":"It seems it will rain tomorrow. In that case, let's cancel the picnic.","id":"Sepertinya besok akan turun hujan. Kalau begitu, ayo batalkan pikniknya."}]},{"pattern":"A。それでは、～B。(A. Soredewa,~B.)","meaning":"Express a change in situation; 'then', 'in that case', 'so'.","meaningId":"Ekspresikan perubahan situasi; 'lalu', 'kalau begitu', 'jadi'.","formation":"A (Statement) + 。それでは、 + B (Follow-up action or statement)","formationId":"A (Pernyataan) + 。それでは、 + B (Tindakan atau pernyataan lanjutan)","examples":[{"jp":"今日は休みだ。それでは、映画を見に行こう。","romaji":"Kyou wa yasumi da. Sore dewa, eiga wo mi ni ikou.","en":"Today is a day off. In that case, let's go see a movie.","id":"Hari ini adalah hari libur. Kalau begitu, ayo kita menonton film."},{"jp":"このパンはもう古いです。それでは、捨てましょう。","romaji":"Kono pan wa mou furui desu. Sore dewa, sutemashou.","en":"This bread is already old. Then, let's throw it away.","id":"Roti ini sudah tua. Kalau begitu, ayo kita buang."},{"jp":"雨が降ってきた。それでは、室内で遊ぼう。","romaji":"Ame ga futtekita. Sore dewa, shitsunai de asobou.","en":"It started raining. In that case, let's play indoors.","id":"Hujan mulai turun. Kalau begitu, ayo bermain di dalam ruangan."},{"jp":"お腹が空いた。それでは、何か食べに行きましょう。","romaji":"Onaka ga suita. Sore dewa, nani ka tabe ni ikimashou.","en":"I'm hungry. So, let's go eat something.","id":"saya lapar. Jadi, ayo kita makan sesuatu."}]},{"pattern":"A。 では、～B。 (A. Dewa, ~B)","meaning":"Indicates a contrast or comparison between A and B; 'As for A, ~B'.","meaningId":"Menunjukkan kontras atau perbandingan antara A dan B; 'Adapun A, ~B'.","formation":"Noun A + では、 + Subject + Predicate B","formationId":"Kata Benda A + では、 + Subjek + Predikat B","examples":[{"jp":"果物では、リンゴが一番好きです。","romaji":"Kudamono dewa, ringo ga ichiban suki desu.","en":"As for fruits, apples are my favorite.","id":"Untuk buah-buahan, apel adalah favoritku."},{"jp":"スポーツでは、サッカーが一番人気です。","romaji":"Supōtsu dewa, sakkā ga ichiban ninki desu.","en":"As for sports, soccer is the most popular.","id":"Sedangkan untuk olah raga, sepak bola adalah yang paling digemari."},{"jp":"今日の天気では、雨が降りそうです。","romaji":"Kyou no tenki dewa, ame ga furisou desu.","en":"As for today's weather, it looks like it will rain.","id":"Untuk cuaca hari ini sepertinya akan turun hujan."},{"jp":"料理では、和食が一番得意です。","romaji":"Ryouri dewa, washoku ga ichiban tokui desu.","en":"As for cooking, I am best at Japanese cuisine.","id":"Untuk memasak, saya paling jago dalam masakan Jepang."}]},{"pattern":"A。でも、～B。(A. Demo, ~B)","meaning":"Used to express contrast between two statements; 'A, but B', 'A, however B'.","meaningId":"Digunakan untuk menyatakan kontras antara dua pernyataan; 'A, tapi B', 'A, bagaimanapun B'.","formation":"Clause A + でも + Clause B","formationId":"Klausul A + でも + Klausul B","examples":[{"jp":"昨日は寒かった。でも、今日は暖かいです。","romaji":"Kinou wa samukatta. Demo, kyou wa atatakai desu.","en":"Yesterday was cold. But today it's warm.","id":"Kemarin dingin. Tapi hari ini hangat."},{"jp":"彼は忙しい。でも、友達と遊ぶ時間がある。","romaji":"Kare wa isogashii. Demo, tomodachi to asobu jikan ga aru.","en":"He is busy. However, he still has time to hang out with friends.","id":"Dia sedang sibuk. Namun, dia masih punya waktu untuk berkumpul dengan teman-temannya."},{"jp":"試験に合格した。でも、まだ勉強を続けています。","romaji":"Shiken ni goukaku shita. Demo, mada benkyou wo tsuzuketeimasu.","en":"I passed the exam. But I'm still continuing to study.","id":"Saya lulus ujian. Tapi aku masih terus belajar."},{"jp":"彼女は有名だ。でも、とても謙虚です。","romaji":"Kanojo wa yuumei da. Demo, totemo kenkyo desu.","en":"She is famous. However, she's very humble.","id":"Dia terkenal. Namun, dia sangat rendah hati."}]},{"pattern":"Aと Bと どちら～","meaning":"Used to ask which of two alternatives is preferred or to compare two things","meaningId":"Digunakan untuk menanyakan alternatif mana yang lebih disukai atau membandingkan dua hal","formation":"Aと Bと どちら + Verb/Adjective/Noun","formationId":"Aと Bと どちら + Kata Kerja/Kata Sifat/Kata Benda","examples":[{"jp":"りんごとみかんとどちらが好きですか。","romaji":"Ringo to mikan to dochira ga suki desu ka?","en":"Which do you like, apples or oranges?","id":"Mana yang kamu suka, apel atau jeruk?"},{"jp":"電車とバスとどちらで行くべきですか。","romaji":"Densha to basu to dochira de iku beki desu ka?","en":"Should I go by train or bus?","id":"Haruskah saya pergi dengan kereta atau bus?"},{"jp":"赤いワンピースと青いワンピースとどちらが似合うと思いますか。","romaji":"Akai wanpiisu to aoi wanpiisu to dochira ga niau to omoimasu ka?","en":"Which do you think suits me better, the red dress or the blue dress?","id":"Menurutmu mana yang lebih cocok untukku, gaun merah atau gaun biru?"},{"jp":"このカメラとあのカメラとどちらのほうが使いやすいですか。","romaji":"Kono kamera to ano kamera to dochira no hou ga tsukaiyasui desu ka?","en":"Which one is easier to use, this camera or that camera?","id":"Mana yang lebih mudah digunakan, kamera ini atau kamera itu?"}]},{"pattern":"AとBと どっち〜 (A to B to docchi〜)","meaning":"Asking which one; 'which', 'A or B'.","meaningId":"Menanyakan yang mana; 'yang', 'A atau B'.","formation":"AとBと どっち + Verb, AかBか どっち + Verb","formationId":"AとBと どっち + Kata Kerja, AかBか どっち + Kata Kerja","examples":[{"jp":"コーヒーと紅茶とどっちが好き？","romaji":"Koohii to koucha to docchi ga suki?","en":"Which do you like, coffee or tea?","id":"Mana yang kamu suka, kopi atau teh?"},{"jp":"映画と音楽とどっちを楽しむ？","romaji":"Eiga to ongaku to docchi o tanoshimu?","en":"Which do you enjoy, movies or music?","id":"Mana yang Anda sukai, film atau musik?"},{"jp":"赤いシャツと青いシャツとどっちを買う？","romaji":"Akai shatsu to aoi shatsu to docchi o kau?","en":"Which one will you buy, the red shirt or the blue shirt?","id":"Kamu mau beli yang mana, baju merah atau baju biru?"},{"jp":"日本語と韓国語とどっちを勉強したい？","romaji":"Nihongo to kankokugo to docchi o benkyou shitai?","en":"Which do you want to study, Japanese or Korean?","id":"Kamu mau belajar yang mana, Jepang atau Korea?"}]},{"pattern":"A は B が〜 (A wa B ga〜)","meaning":"Indicates that there is something unique or different about A and describes what is special about it.","meaningId":"Menunjukkan bahwa ada sesuatu yang unik atau berbeda pada A dan menjelaskan apa yang istimewa darinya.","formation":"A は (Topic) + B が (Characteristic/Feature) + Description/Action","formationId":"A は (Topik) + B が (Karakteristik/Fitur) + Deskripsi/Tindakan","examples":[{"jp":"彼女は髪が長いです。","romaji":"Kanojo wa kami ga nagai desu.","en":"What's special about her is that she has long hair.","id":"Yang istimewa dari dia adalah rambutnya yang panjang."},{"jp":"このレストランは雰囲気が良いです。","romaji":"Kono resutoran wa fun'iki ga ii desu.","en":"What's great about this restaurant is the atmosphere.","id":"Yang menarik dari restoran ini adalah suasananya."},{"jp":"私は朝ごはんが一番好きです。","romaji":"Watashi wa asagohan ga ichiban suki desu.","en":"What I like the most is breakfast.","id":"Yang paling saya suka adalah sarapan."},{"jp":"彼は英語が得意です。","romaji":"Kare wa eigo ga tokui desu.","en":"He is particularly good at English.","id":"Dia sangat pandai berbahasa Inggris."}]},{"pattern":"A は B より～","meaning":"Express a comparison between A and B; 'A is more/less than B'.","meaningId":"Nyatakan perbandingan antara A dan B; 'A lebih/kurang dari B'.","formation":"A は B より + Adjective","formationId":"A は B より + Kata Sifat","examples":[{"jp":"このジュースはあのジュースより甘いです。","romaji":"Kono juusu wa ano juusu yori amai desu.","en":"This juice is sweeter than that juice.","id":"Jus ini lebih manis dari jus itu."},{"jp":"夏は冬より暑いです。","romaji":"Natsu wa fuyu yori atsui desu.","en":"Summer is hotter than winter.","id":"Musim panas lebih panas daripada musim dingin."},{"jp":"彼女は私より速く走ります。","romaji":"Kanojo wa watashi yori hayaku hashirimasu.","en":"She runs faster than me.","id":"Dia berlari lebih cepat dariku."},{"jp":"スーパーはコンビニより安いです。","romaji":"Suupaa wa konbini yori yasui desu.","en":"The supermarket is cheaper than the convenience store.","id":"Supermarket lebih murah dibandingkan minimarket."}]},{"pattern":"A より B のほうが～","meaning":"Used to compare two items; 'B is more ～ than A'.","meaningId":"Digunakan untuk membandingkan dua item; 'B lebih ～ dari A'.","formation":"A + より + B + のほうが + Adjective","formationId":"A + より + B + のほうが + Kata Sifat","examples":[{"jp":"ピザよりハンバーガーのほうが美味しい。","romaji":"Piza yori hanbaagaa no hou ga oishii.","en":"Hamburgers are more delicious than pizza.","id":"Hamburger lebih enak dari pada pizza."},{"jp":"夏より冬のほうが寒い。","romaji":"Natsu yori fuyu no hou ga samui.","en":"Winter is colder than summer.","id":"Musim dingin lebih dingin dari musim panas."},{"jp":"ここよりそこのほうが静かです。","romaji":"Koko yori soko no hou ga shizuka desu.","en":"There is quieter than here.","id":"Di sana lebih tenang daripada di sini."},{"jp":"車より電車のほうが速い。","romaji":"Kuruma yori densha no hou ga hayai.","en":"Trains are faster than cars.","id":"Kereta api lebih cepat dari mobil."}]},{"pattern":"い-Adjective く + Verb (i-Adjective + ku + Verb)","meaning":"Used to connect an い-adjective to a verb, modifying the verb (adverbial usage).","meaningId":"Digunakan untuk menghubungkan kata sifat い ke kata kerja, memodifikasi kata kerja (penggunaan kata keterangan).","formation":"い-Adjective (remove い) + く + Verb","formationId":"い-Kata sifat (hapus い) + く + Kata Kerja","examples":[{"jp":"彼は速く走りました。","romaji":"Kare wa hayaku hashirimashita.","en":"He ran quickly.","id":"Dia berlari dengan cepat."},{"jp":"この料理は美味しく食べました。","romaji":"Kono ryouri wa oishiku tabemashita.","en":"I enjoyed eating this dish.","id":"Saya menikmati makan hidangan ini."},{"jp":"彼女は優しく話します。","romaji":"Kanojo wa yasashiku hanashimasu.","en":"She speaks kindly.","id":"Dia berbicara dengan ramah."},{"jp":"母は忙しく仕事をしています。","romaji":"Haha wa isogashiku shigoto o shite imasu.","en":"My mother is working busily.","id":"Ibuku sibuk bekerja."}]},{"pattern":"い-Adjective く します (i-Adjective ku shimasu)","meaning":"Use an い-adjective to express 'to make' or 'to become'.","meaningId":"Gunakan kata sifat い untuk menyatakan 'membuat' atau 'menjadi'.","formation":"い-Adjective (remove い) + くします","formationId":"い-Kata sifat (hapus い) + くします","examples":[{"jp":"部屋を明るくします。","romaji":"Heya o akaruku shimasu.","en":"I will make the room brighter.","id":"Saya akan membuat ruangan lebih terang."},{"jp":"友達の気分を楽しくします。","romaji":"Tomodachi no kibun o tanoshiku shimasu.","en":"I will make my friend’s mood more pleasant.","id":"Saya akan membuat suasana hati teman saya lebih menyenangkan."},{"jp":"仕事が簡単になるように、やり方を早くします。","romaji":"Shigoto ga kantan ni naru you ni, yarikata o hayaku shimasu.","en":"I will make the way of doing things faster so that the work becomes easier.","id":"Saya akan membuat cara mengerjakan sesuatu menjadi lebih cepat sehingga pekerjaan menjadi lebih mudah."},{"jp":"食べ物を美味しくします。","romaji":"Tabemono o oishiku shimasu.","en":"I will make the food delicious.","id":"Aku akan membuat makanannya enak."}]},{"pattern":"い-Adjective: Negative Polite Form","meaning":"Change an い-adjective into a polite negative form with ～くないです (or ～くありません).","meaningId":"Ubah kata sifat い menjadi bentuk negatif yang sopan dengan ～くないです (atau ～くありません).","formation":"い-Adjective (remove い) + くないです","formationId":"い-Kata sifat (hapus い) + くないです","examples":[{"jp":"このピザは美味しくないです。","romaji":"Kono piza wa oishiku nai desu.","en":"This pizza is not delicious.","id":"Pizza ini tidak enak."},{"jp":"この部屋は広くないです。","romaji":"Kono heya wa hiroku nai desu.","en":"This room is not spacious.","id":"Ruangan ini tidak luas."},{"jp":"彼の意見は面白くないです。","romaji":"Kare no iken wa omoshiroku nai desu.","en":"His opinion is not interesting.","id":"Pendapatnya tidak menarik."},{"jp":"その映画は楽しくありません。","romaji":"Sono eiga wa tanoshiku arimasen.","en":"That movie is not enjoyable.","id":"Film itu tidak menyenangkan."}]},{"pattern":"い-Adjective て (i-Adjective + te~)","meaning":"Used to connect two or more い-adjectives to describe something.","meaningId":"Digunakan untuk menghubungkan dua atau lebih kata sifat い untuk mendeskripsikan sesuatu.","formation":"い-Adjective (remove い) + くて + い-Adjective","formationId":"い-Kata sifat (hapus い) + くて + い-Kata sifat","examples":[{"jp":"このリンゴは甘くて美味しいです。","romaji":"Kono ringo wa amakute oishii desu.","en":"This apple is sweet and delicious.","id":"Apel ini manis dan enak."},{"jp":"彼女は優しくてかわいいです。","romaji":"Kanojo wa yasashikute kawaii desu.","en":"She is kind and cute.","id":"Dia baik dan manis."},{"jp":"映画は面白くて感動的でした。","romaji":"Eiga wa omoshirokute kandouteki deshita.","en":"The movie was interesting and moving.","id":"Filmnya menarik dan mengharukan."},{"jp":"この部屋は広くて明るいです。","romaji":"Kono heya wa hirokute akarui desu.","en":"This room is spacious and bright.","id":"Ruangan ini luas dan terang."}]},{"pattern":"な-Adjective に + Verb","meaning":"Turn a な-adjective into an adverb by adding に.","meaningId":"Ubah kata sifat な menjadi kata keterangan dengan menambahkan に.","formation":"な-Adjective (remove な) + に + Verb","formationId":"な-Kata sifat (hapus な) + に + Kata Kerja","examples":[{"jp":"彼は静かに話す。","romaji":"Kare wa shizuka ni hanasu.","en":"He speaks quietly.","id":"Dia berbicara dengan pelan."},{"jp":"部屋をきれいに掃除した。","romaji":"Heya o kirei ni souji shita.","en":"I cleaned the room neatly.","id":"Saya membersihkan kamar dengan rapi."},{"jp":"彼女は元気に働いています。","romaji":"Kanojo wa genki ni hataraite imasu.","en":"She works energetically.","id":"Dia bekerja dengan penuh semangat."},{"jp":"先生は親切に説明してくれる。","romaji":"Sensei wa shinsetsu ni setsumei shite kureru.","en":"The teacher explains kindly.","id":"Guru menjelaskan dengan ramah."}]},{"pattern":"な-Adjective で～ (na-Adjective de~)","meaning":"Usage of で to connect or add information with a な-adjective.","meaningId":"Penggunaan で untuk menghubungkan atau menambahkan informasi dengan kata sifat な.","formation":"な-Adjective + で","formationId":"な-Kata sifat + で","examples":[{"jp":"彼は綺麗で優しい女性が好きです。","romaji":"Kare wa kirei de yasashii josei ga suki desu.","en":"He likes women who are beautiful and kind.","id":"Dia menyukai wanita yang cantik dan baik hati."},{"jp":"この料理は健康的で、元気な気分になります。","romaji":"Kono ryouri wa kenkouteki de, genki na kibun ni narimasu.","en":"This dish is healthy and makes you feel energetic.","id":"Hidangan ini menyehatkan dan membuat Anda merasa energik."},{"jp":"彼は静かで落ち着いた環境で仕事をしたい。","romaji":"Kare wa shizuka de ochitsuita kankyou de shigoto o shitai.","en":"He wants to work in a quiet and calm environment.","id":"Dia ingin bekerja di lingkungan yang tenang dan tenteram."},{"jp":"この部屋は清潔で気持ちがいいです。","romaji":"Kono heya wa seiketsu de kimochi ga ii desu.","en":"This room is clean and feels good.","id":"Ruangan ini bersih dan terasa nyaman."}]},{"pattern":"な-Adjective に します (na-Adjective ni shimasu)","meaning":"Expressing a decision or preference with a な-adjective.","meaningId":"Mengekspresikan keputusan atau preferensi dengan kata sifat な.","formation":"な-Adjective + に + します","formationId":"な-Kata sifat + に + します","examples":[{"jp":"静かにします。","romaji":"Shizuka ni shimasu.","en":"I will be quiet.","id":"Saya akan diam."},{"jp":"部屋をきれいにします。","romaji":"Heya o kirei ni shimasu.","en":"I will make the room clean.","id":"Saya akan membersihkan ruangan."},{"jp":"明日の会議は簡単にします。","romaji":"Ashita no kaigi wa kantan ni shimasu.","en":"I will make tomorrow’s meeting simple.","id":"Saya akan membuat pertemuan besok menjadi sederhana."},{"jp":"健康的な食事にします。","romaji":"Kenkou-teki na shokuji ni shimasu.","en":"I will choose a healthy meal.","id":"Saya akan memilih makanan yang sehat."}]},{"pattern":"な-Adjective に なります (na-Adjective ni narimasu)","meaning":"Express a change or transformation into a state described by the な-adjective.","meaningId":"Nyatakan perubahan atau transformasi menjadi keadaan yang dijelaskan oleh kata sifat な.","formation":"な-Adjective (remove な) + に + なります","formationId":"な-Kata sifat (hapus な) + に + なります","examples":[{"jp":"この部屋は静かになります。","romaji":"Kono heya wa shizuka ni narimasu.","en":"This room becomes quiet.","id":"Ruangan ini menjadi sunyi."},{"jp":"彼女はきれいになります。","romaji":"Kanojo wa kirei ni narimasu.","en":"She becomes beautiful.","id":"Dia menjadi cantik."},{"jp":"彼は元気になります。","romaji":"Kare wa genki ni narimasu.","en":"He becomes energetic.","id":"Dia menjadi energik."},{"jp":"町はにぎやかになります。","romaji":"Machi wa nigiyaka ni narimasu.","en":"The town becomes lively.","id":"Kota menjadi hidup."}]},{"pattern":"Noun か Noun か～","meaning":"Expresses choice or alternatives; 'either', 'or'.","meaningId":"Mengekspresikan pilihan atau alternatif; 'salah satu', 'atau'.","formation":"Noun1 + か + Noun2 + か～","formationId":"Kata Benda1 + か + Kata Benda2 + か～","examples":[{"jp":"今日、映画を見るか、散歩するかどちらにしますか？","romaji":"Kyou, eiga wo miru ka, sanpo suru ka dochira ni shimasu ka?","en":"Will we watch a movie or go for a walk today?","id":"Akankah kita menonton film atau berjalan-jalan hari ini?"},{"jp":"コーヒーか紅茶か、一つだけ選んでください。","romaji":"Koohii ka koucha ka, hitotsu dake erande kudasai.","en":"Please choose only one, either coffee or tea.","id":"Silakan pilih salah satu saja, baik kopi atau teh."},{"jp":"電車かバスを使って、学校に行くつもりです。","romaji":"Densha ka basu o tsukatte, gakkou ni iku tsumori desu.","en":"I plan to go to school using either the train or the bus.","id":"Saya berencana pergi ke sekolah menggunakan kereta atau bus."},{"jp":"週末は山に登るか海に行くか、まだ決めていません。","romaji":"Shuumatsu wa yama ni noboru ka umi ni iku ka, mada kimete imasen.","en":"I haven't decided whether to climb the mountain or go to the beach this weekend.","id":"Saya belum memutuskan apakah akan mendaki gunung atau pergi ke pantai akhir pekan ini."}]},{"pattern":"Noun が できます","meaning":"Express the ability to do something.","meaningId":"Ekspresikan kemampuan untuk melakukan sesuatu.","formation":"Noun + が + できます","formationId":"Kata Benda + が + できます","examples":[{"jp":"英語ができます。","romaji":"Eigo ga dekimasu.","en":"I can speak English.","id":"Saya bisa berbicara bahasa Inggris."},{"jp":"料理ができます。","romaji":"Ryouri ga dekimasu.","en":"I can cook.","id":"saya bisa memasak."},{"jp":"彼は泳ぎができます。","romaji":"Kare wa oyogi ga dekimasu.","en":"He can swim.","id":"Dia bisa berenang."},{"jp":"彼女はピアノができます。","romaji":"Kanojo wa piano ga dekimasu.","en":"She can play the piano.","id":"Dia bisa bermain piano."}]},{"pattern":"Noun がほしいです (〜ga hoshii desu)","meaning":"Express a desire or wanting something; 'I want', 'I would like'.","meaningId":"Mengungkapkan keinginan atau menginginkan sesuatu; 'Saya ingin', 'Saya ingin'.","formation":"Noun + が + ほしいです","formationId":"Kata benda + が + ほしいです","examples":[{"jp":"新しい車がほしいです。","romaji":"Atarashii kuruma ga hoshii desu.","en":"I want a new car.","id":"Saya ingin mobil baru."},{"jp":"コーヒーがほしいです。","romaji":"Koohii ga hoshii desu.","en":"I would like some coffee.","id":"Saya ingin kopi."},{"jp":"彼女は花がほしいです。","romaji":"Kanojo wa hana ga hoshii desu.","en":"She wants flowers.","id":"Dia ingin bunga."},{"jp":"友達がほしいです。","romaji":"Tomodachi ga hoshii desu.","en":"I want a friend.","id":"Saya ingin seorang teman."}]},{"pattern":"Noun から Noun まで","meaning":"Expresses a range; 'from...to', 'between...and'.","meaningId":"Mengekspresikan rentang; 'dari...ke', 'antara...dan'.","formation":"Noun1 + から + Noun2 + まで","formationId":"Kata Benda1 + から + Kata Benda2 + まで","examples":[{"jp":"朝9時から午後5時まで働きます。","romaji":"Asa ku-ji kara gogo go-ji made hatarakimasu.","en":"I work from 9 AM to 5 PM.","id":"Saya bekerja dari jam 9 pagi sampai jam 5 sore."},{"jp":"東京から大阪まで電車で行く。","romaji":"Toukyou kara Osaka made densha de iku.","en":"I will go by train from Tokyo to Osaka.","id":"Saya akan pergi dengan kereta api dari Tokyo ke Osaka."},{"jp":"地下鉄は午前6時から深夜まで運行しています。","romaji":"Chikatetsu wa gozen roku-ji kara shin'ya made unkou shite imasu.","en":"The subway runs from 6 AM until midnight.","id":"Kereta bawah tanah beroperasi mulai pukul 06.00 hingga tengah malam."},{"jp":"月曜日から金曜日まで学校に通います。","romaji":"Getsuyoubi kara Kinyoubi made gakkou ni kayoimasu.","en":"I attend school from Monday to Friday.","id":"Saya bersekolah dari Senin sampai Jumat."}]},{"pattern":"Noun くらい～","meaning":"Express the extent or degree of something; 'about', 'approximately', 'at least'.","meaningId":"Menyatakan luas atau derajat sesuatu; 'tentang', 'kira-kira', 'setidaknya'.","formation":"Noun + くらい","formationId":"Kata benda + くらい","examples":[{"jp":"この本は三百ページくらいあります。","romaji":"Kono hon wa sanbyaku peeji kurai arimasu.","en":"This book has about 300 pages.","id":"Buku ini memiliki sekitar 300 halaman."},{"jp":"彼の家まで歩いて20分くらいかかります。","romaji":"Kare no ie made aruite nijuppun kurai kakarimasu.","en":"It takes about 20 minutes to walk to his house.","id":"Dibutuhkan sekitar 20 menit berjalan kaki ke rumahnya."},{"jp":"明日は暑くて、30度くらいになるでしょう。","romaji":"Ashita wa atsukute, sanjuu-do kurai ni naru deshou.","en":"Tomorrow will be hot, about 30 degrees.","id":"Besok akan panas, sekitar 30 derajat."},{"jp":"この料理を作るのに、材料は500円くらい必要です。","romaji":"Kono ryouri o tsukuru no ni, zairyou wa gohyaku-en kurai hitsuyou desu.","en":"You need about 500 yen worth of ingredients to make this dish.","id":"Anda membutuhkan bahan-bahan senilai sekitar 500 yen untuk membuat hidangan ini."}]},{"pattern":"Noun ぐらい～","meaning":"Express an approximate amount or degree; 'about', 'approximately'.","meaningId":"Nyatakan perkiraan jumlah atau derajat; 'tentang', 'kira-kira'.","formation":"Noun + ぐらい","formationId":"Kata benda + ぐらい","examples":[{"jp":"一日中勉強したので、１０時間ぐらい勉強しました。","romaji":"Ichinichijuu benkyou shita node, juu-jikan gurai benkyou shimashita.","en":"I studied all day, so I studied for about 10 hours.","id":"Saya belajar sepanjang hari, jadi saya belajar sekitar 10 jam."},{"jp":"この本は１００ページぐらいある。","romaji":"Kono hon wa hyaku peeji gurai aru.","en":"This book has about 100 pages.","id":"Buku ini memiliki sekitar 100 halaman."},{"jp":"彼は果物を５個ぐらい食べました。","romaji":"Kare wa kudamono o go-ko gurai tabemashita.","en":"He ate about 5 pieces of fruit.","id":"Dia makan sekitar 5 buah buah."},{"jp":"駅から家まで歩いて２０分ぐらいかかります。","romaji":"Eki kara ie made aruite nijuppun gurai kakarimasu.","en":"It takes about 20 minutes to walk from the station to my house.","id":"Dibutuhkan sekitar 20 menit berjalan kaki dari stasiun ke rumah saya."}]},{"pattern":"Noun ごろ～ (Noun + goro～)","meaning":"Expresses 'around' or 'about' a certain time or age.","meaningId":"Menyatakan 'sekitar' atau 'tentang' waktu atau usia tertentu.","formation":"Noun + ごろ","formationId":"Kata benda + ごろ","examples":[{"jp":"昼ごろに電話してください。","romaji":"Hiru goro ni denwa shite kudasai.","en":"Please call me around noon.","id":"Tolong telepon saya sekitar tengah hari."},{"jp":"彼は10歳ごろに日本に来ました。","romaji":"Kare wa juu-sai goro ni Nihon ni kimashita.","en":"He came to Japan around the age of 10.","id":"Dia datang ke Jepang sekitar usia 10 tahun."},{"jp":"午後３時ごろに会いましょう。","romaji":"Gogo san-ji goro ni aimashou.","en":"Let's meet around 3 PM.","id":"Mari kita bertemu sekitar jam 3 sore."},{"jp":"昨日の夜8時ごろに帰りました。","romaji":"Kinou no yoru hachi-ji goro ni kaerimashita.","en":"I returned home last night around 8 o'clock.","id":"Saya pulang ke rumah tadi malam sekitar jam 8 malam."}]},{"pattern":"Noun だけ〜 (〜dake)","meaning":"Indicates 'only', 'just', or 'merely'.","meaningId":"Menunjukkan 'hanya', 'hanya', atau 'hanya'.","formation":"Noun + だけ, Verb-casual + だけ, い-Adjective + だけ, な-Adjective-な + だけ","formationId":"Kata Benda + だけ, Kata Kerja-kasual + だけ, い-Kata Sifat + だけ, な-Kata Sifat-な + だけ","examples":[{"jp":"コーヒーだけ飲んで、帰りました。","romaji":"Koohii dake nonde, kaerimashita.","en":"I only drank coffee and went home.","id":"Saya hanya minum kopi dan pulang."},{"jp":"この本は二十ページだけ読んだ。","romaji":"Kono hon wa nijuu peeji dake yonda.","en":"I only read twenty pages of this book.","id":"Saya hanya membaca dua puluh halaman buku ini."},{"jp":"彼女はとても速いですが、走るだけでなく、考えるのも速いです。","romaji":"Kanojo wa totemo hayai desu ga, hashiru dake denaku, kangaeru no mo hayai desu.","en":"She is very fast, not only at running but also at thinking.","id":"Dia sangat cepat, tidak hanya dalam berlari tetapi juga dalam berpikir."},{"jp":"この部屋は寝るだけの場所です。","romaji":"Kono heya wa neru dake no basho desu.","en":"This room is a place only for sleeping.","id":"Ruangan ini hanyalah tempat untuk tidur."}]},{"pattern":"Nounで～","meaning":"Indicate a place or means for an action or situation; 'at, in, on', 'using', or 'by means of'.","meaningId":"Tunjukkan tempat atau sarana untuk suatu tindakan atau situasi; 'di, di, pada', 'menggunakan', atau 'melalui'.","formation":"Noun + で","formationId":"Kata benda + で","examples":[{"jp":"図書館で勉強します。","romaji":"Toshokan de benkyou shimasu.","en":"I study at the library.","id":"Saya belajar di perpustakaan."},{"jp":"バスで学校に行きます。","romaji":"Basu de gakkou ni ikimasu.","en":"I go to school by bus.","id":"Saya pergi ke sekolah dengan bus."},{"jp":"鉛筆で書きました。","romaji":"Enpitsu de kakimashita.","en":"I wrote it using a pencil.","id":"Saya menulisnya menggunakan pensil."},{"jp":"英語で話しましょう。","romaji":"Eigo de hanashimashou.","en":"Let's talk in English.","id":"Mari kita bicara dalam bahasa Inggris."}]},{"pattern":"Noun と～","meaning":"Express 'with', 'and' or 'together with' when connecting nouns.","meaningId":"Ekspresikan 'dengan', 'dan' atau 'bersama dengan' ketika menghubungkan kata benda.","formation":"Noun1 + と + Noun2","formationId":"Kata Benda1 + と + Kata Benda2","examples":[{"jp":"リンゴとバナナを買いました。","romaji":"Ringo to banana wo kaimashita.","en":"I bought apples and bananas.","id":"Saya membeli apel dan pisang."},{"jp":"友達と映画を見に行きます。","romaji":"Tomodachi to eiga wo mi ni ikimasu.","en":"I will go to watch a movie with my friend.","id":"Saya akan pergi menonton film bersama teman saya."},{"jp":"父と母と一緒に旅行しました。","romaji":"Chichi to haha to issho ni ryokou shimashita.","en":"I traveled together with my father and mother.","id":"Saya bepergian bersama ayah dan ibu saya."},{"jp":"彼と彼女は結婚しました。","romaji":"Kare to kanojo wa kekkon shimashita.","en":"He and she got married.","id":"Dia dan dia menikah."}]},{"pattern":"Noun に～","meaning":"Express a specific direction, target or purpose; 'to', 'toward', 'for'.","meaningId":"Mengungkapkan arah, sasaran, atau tujuan tertentu; 'ke', 'menuju', 'untuk'.","formation":"Noun + に","formationId":"Kata benda + に","examples":[{"jp":"彼女にプレゼントをあげました。","romaji":"Kanojo ni purezento wo agemashita.","en":"I gave a present to her.","id":"Saya memberikan hadiah padanya."},{"jp":"日本に行きます。","romaji":"Nihon ni ikimasu.","en":"I am going to Japan.","id":"Saya akan ke Jepang."},{"jp":"6時に集合しましょう。","romaji":"Roku-ji ni shuugou shimashou.","en":"Let's meet at 6 o'clock.","id":"Mari kita bertemu jam 6 sore."},{"jp":"友達に手紙を書きます。","romaji":"Tomodachi ni tegami wo kakimasu.","en":"I will write a letter to my friend.","id":"Saya akan menulis surat kepada teman saya."}]},{"pattern":"Noun に 帰ります","meaning":"Express going back or returning to a place: 'to return to', 'to go back to'.","meaningId":"Ekspresikan kembali atau kembali ke suatu tempat: 'kembali ke', 'kembali ke'.","formation":"Noun + に + 帰ります","formationId":"Kata benda + に + 帰ります","examples":[{"jp":"夏休みが終わったら、学校に帰ります。","romaji":"Natsuyasumi ga owattara, gakkou ni kaerimasu.","en":"When summer vacation ends, I'll go back to school.","id":"Saat liburan musim panas berakhir, aku akan kembali ke sekolah."},{"jp":"買い物を終えたら、家に帰ります。","romaji":"Kaimono o oetara, ie ni kaerimasu.","en":"After finishing shopping, I will go back home.","id":"Setelah selesai berbelanja, saya akan kembali ke rumah."},{"jp":"今週末、実家に帰ります。","romaji":"Konshuumatsu, jikka ni kaerimasu.","en":"I'm going back to my parents' home this weekend.","id":"Saya akan kembali ke rumah orang tua saya akhir pekan ini."},{"jp":"友達と旅行に行ったあと、東京に帰ります。","romaji":"Tomodachi to ryokou ni itta ato, Toukyou ni kaerimasu.","en":"After traveling with my friend, I'll return to Tokyo.","id":"Setelah bepergian dengan teman saya, saya akan kembali ke Tokyo."}]},{"pattern":"Noun に します","meaning":"Express a choice or decision; 'choose', 'decide on'.","meaningId":"Ekspresikan pilihan atau keputusan; 'memilih', 'memutuskan'.","formation":"Noun + に します","formationId":"Kata benda + に します","examples":[{"jp":"今日の昼ご飯は寿司にします。","romaji":"Kyou no hirugohan wa sushi ni shimasu.","en":"I'll choose sushi for today's lunch.","id":"Saya akan memilih sushi untuk makan siang hari ini."},{"jp":"この靴を買うか迷っていますが、赤い色の方にします。","romaji":"Kono kutsu wo kau ka mayotteimasu ga, akai iro no hou ni shimasu.","en":"I was hesitating about which shoes to buy, but I'll go with the red ones.","id":"Tadinya aku ragu mau beli sepatu yang mana, tapi aku pilih yang merah."},{"jp":"休みの日に何をするか決めた。映画館に行くことにします。","romaji":"Yasumi no hi ni nani wo suru ka kimeta. Eigakan ni iku koto ni shimasu.","en":"I've decided what to do on my day off. I'll go to the movie theater.","id":"Aku sudah memutuskan apa yang harus kulakukan di hari liburku. Aku akan pergi ke bioskop."},{"jp":"フランス語とスペイン語のどちらを勉強するか悩んだが、フランス語にします。","romaji":"Furansugo to Supeingo no dochira wo benkyou suru ka nayanda ga, Furansugo ni shimasu.","en":"I was torn between studying French and Spanish, but I decided on French.","id":"Saya bingung antara belajar bahasa Prancis dan Spanyol, tetapi saya memutuskan untuk memilih bahasa Prancis."}]},{"pattern":"Noun に なります","meaning":"Expresses change or becoming something; 'to become', 'to turn into', 'to be'.","meaningId":"Mengekspresikan perubahan atau menjadi sesuatu; 'menjadi', 'menjadi', 'menjadi'.","formation":"Noun + に + なります","formationId":"Kata benda + に + なります","examples":[{"jp":"彼は医者になります。","romaji":"Kare wa isha ni narimasu.","en":"He will become a doctor.","id":"Dia akan menjadi seorang dokter."},{"jp":"この茶色の葉が赤になります。","romaji":"Kono chairo no ha ga aka ni narimasu.","en":"These brown leaves will turn red.","id":"Daun berwarna coklat ini akan berubah menjadi merah."},{"jp":"料理が冷めたら、美味しくなくなります。","romaji":"Ryouri ga sametara, oishikunaku narimasu.","en":"When the dish cools down, it becomes less delicious.","id":"Saat masakan sudah dingin, rasanya menjadi kurang enak."},{"jp":"来年、東京オリンピックになります。","romaji":"Rainen, Toukyou Orinpikku ni narimasu.","en":"Next year, it will be the Tokyo Olympics.","id":"Tahun depan adalah Olimpiade Tokyo."}]},{"pattern":"Noun に 来ます","meaning":"Used to express coming to a place.","meaningId":"Digunakan untuk menyatakan datang ke suatu tempat.","formation":"Noun + に + 来ます (kimasu)","formationId":"Kata benda + に + 来ます (kimasu)","examples":[{"jp":"友達が私の家に来ます。","romaji":"Tomodachi ga watashi no ie ni kimasu.","en":"My friend will come to my house.","id":"Temanku akan datang ke rumahku."},{"jp":"今晩、父が駅に迎えに来ます。","romaji":"Konban, chichi ga eki ni mukae ni kimasu.","en":"Tonight, my father will come to pick me up at the station.","id":"Malam ini, ayahku akan datang menjemputku di stasiun."},{"jp":"明日、先生が学校に来ます。","romaji":"Ashita, sensei ga gakkou ni kimasu.","en":"Tomorrow, the teacher will come to school.","id":"Besok, guru akan datang ke sekolah."},{"jp":"有名な歌手がこの街に来ます。","romaji":"Yuumei na kashu ga kono machi ni kimasu.","en":"A famous singer will come to this town.","id":"Seorang penyanyi terkenal akan datang ke kota ini."}]},{"pattern":"Noun に 行きます","meaning":"Used to express going to a location.","meaningId":"Digunakan untuk menyatakan pergi ke suatu lokasi.","formation":"Noun + に + 行きます","formationId":"Kata benda + に + 行きます","examples":[{"jp":"学校に行きます。","romaji":"Gakkou ni ikimasu.","en":"I will go to school.","id":"Saya akan pergi ke sekolah."},{"jp":"明日、スーパーに行きます。","romaji":"Ashita, suupaa ni ikimasu.","en":"I will go to the supermarket tomorrow.","id":"Saya akan pergi ke supermarket besok."},{"jp":"週末に映画館に行きます。","romaji":"Shuumatsu ni eigakan ni ikimasu.","en":"I will go to the movie theater on the weekend.","id":"Saya akan pergi ke bioskop pada akhir pekan."},{"jp":"夏休みに海に行きます。","romaji":"Natsu yasumi ni umi ni ikimasu.","en":"I will go to the sea during the summer vacation.","id":"Saya akan pergi ke laut selama liburan musim panas."}]},{"pattern":"Noun の あとで","meaning":"Expresses the order of events; 'after', 'later than'.","meaningId":"Mengekspresikan urutan kejadian; 'setelah', 'lebih lambat'.","formation":"Noun + の + あとで","formationId":"Kata benda + の + あとで","examples":[{"jp":"朝ご飯のあとで、歯を磨きます。","romaji":"Asagohan no atode, ha wo migakimasu.","en":"After breakfast, I brush my teeth.","id":"Setelah sarapan, saya menyikat gigi."},{"jp":"映画のあとで、レストランで夕食を食べました。","romaji":"Eiga no atode, resutoran de yuushoku o tabemashita.","en":"After the movie, we ate dinner at a restaurant.","id":"Setelah menonton film, kami makan malam di sebuah restoran."},{"jp":"会議のあとで、上司と話し合います。","romaji":"Kaigi no atode, joushi to hanashiaimasu.","en":"I will discuss with my boss after the meeting.","id":"Saya akan berdiskusi dengan atasan saya setelah rapat."},{"jp":"晩ご飯のあとで、散歩に行きました。","romaji":"Bangohan no atode, sanpo ni ikimashita.","en":"After dinner, I went for a walk.","id":"Setelah makan malam, saya pergi jalan-jalan."}]},{"pattern":"Noun の 前に","meaning":"Used to describe a location or position 'in front of' a noun.","meaningId":"Digunakan untuk menggambarkan suatu lokasi atau posisi 'di depan' suatu kata benda.","formation":"Noun + の + 前に","formationId":"Kata benda + の + 前に","examples":[{"jp":"駅の前にコンビニがあります。","romaji":"Eki no mae ni konbini ga arimasu.","en":"There is a convenience store in front of the station.","id":"Ada toko serba ada di depan stasiun."},{"jp":"家の前に車を止めてください。","romaji":"Ie no mae ni kuruma wo tomete kudasai.","en":"Please park the car in front of the house.","id":"Silakan parkir mobil di depan rumah."},{"jp":"私の前に彼が立っていました。","romaji":"Watashi no mae ni kare ga tatte imashita.","en":"He was standing in front of me.","id":"Dia berdiri di depanku."},{"jp":"ホテルの前にタクシーが来た。","romaji":"Hoteru no mae ni takushii ga kita.","en":"A taxi came in front of the hotel.","id":"Sebuah taksi datang di depan hotel."}]},{"pattern":"Noun は～ (Noun wa〜)","meaning":"Used to mark the topic of a sentence; 'as for', 'speaking of'.","meaningId":"Digunakan untuk menandai topik sebuah kalimat; 'adapun', 'berbicara tentang'.","formation":"Noun + は","formationId":"Kata benda + は","examples":[{"jp":"私は日本の料理が好きです。","romaji":"Watashi wa Nihon no ryouri ga suki desu.","en":"As for me, I like Japanese cuisine.","id":"Bagi saya, saya suka masakan Jepang."},{"jp":"彼は英語が上手です。","romaji":"Kare wa eigo ga jouzu desu.","en":"As for him, he is good at English.","id":"Sedangkan dia, dia pandai berbahasa Inggris."},{"jp":"この本は面白いです。","romaji":"Kono hon wa omoshiroi desu.","en":"As for this book, it's interesting.","id":"Untuk buku ini menarik."},{"jp":"今日は暑いですね。","romaji":"Kyou wa atsui desu ne.","en":"Speaking of today, it's hot, isn't it?","id":"Ngomong-ngomong hari ini panas sekali ya?"}]},{"pattern":"Noun も〜","meaning":"Indicates that the action or state is the same for multiple items or people; 'also', 'as well'.","meaningId":"Menunjukkan bahwa tindakan atau keadaannya sama untuk beberapa item atau orang; 'juga', 'juga'.","formation":"Noun + も","formationId":"Kata benda + も","examples":[{"jp":"私も日本語を勉強しています。","romaji":"Watashi mo nihongo wo benkyou shiteimasu.","en":"I am also studying Japanese.","id":"Saya juga sedang belajar bahasa Jepang."},{"jp":"彼もケーキが好きです。","romaji":"Kare mo keeki ga suki desu.","en":"He also likes cake.","id":"Dia juga suka kue."},{"jp":"東京も大阪も観光スポットがたくさんあります。","romaji":"Toukyou mo Oosaka mo kankou supotto ga takusan arimasu.","en":"There are many tourist spots in both Tokyo and Osaka.","id":"Ada banyak tempat wisata di Tokyo dan Osaka."},{"jp":"この映画もあの映画も面白かった。","romaji":"Kono eiga mo ano eiga mo omoshirokatta.","en":"Both this movie and that movie were interesting.","id":"Baik film ini maupun film itu menarik."}]},{"pattern":"Noun や Noun など～","meaning":"Lists items or examples but not exhaustively; 'such as', 'like', 'and so on'.","meaningId":"Mencantumkan item atau contoh tetapi tidak menyeluruh; 'seperti', 'seperti', 'dan seterusnya'.","formation":"Noun1 + や + Noun2 + など","formationId":"Kata benda1 + や + Kata benda2 + など","examples":[{"jp":"彼は野菜や果物などを食べるのが好きです。","romaji":"Kare wa yasai ya kudamono nado o taberu no ga suki desu.","en":"He likes to eat things like vegetables and fruits.","id":"Dia suka makan sesuatu seperti sayuran dan buah-buahan."},{"jp":"日本の都市や東京、大阪などに行きたいです。","romaji":"Nihon no toshi ya Toukyou, Oosaka nado ni ikitai desu.","en":"I want to go to Japanese cities such as Tokyo, Osaka, and so on.","id":"Saya ingin pergi ke kota-kota Jepang seperti Tokyo, Osaka, dan sebagainya."},{"jp":"彼女は猫や犬など動物が好きです。","romaji":"Kanojo wa neko ya inu nado doubutsu ga suki desu.","en":"She likes animals like cats, dogs, and so on.","id":"Dia menyukai binatang seperti kucing, anjing, dan sebagainya."},{"jp":"この本屋では漫画や小説などたくさんの本が売られています。","romaji":"Kono honya de wa manga ya shousetsu nado takusan no hon ga urarete imasu.","en":"In this bookstore, many books such as manga and novels are sold.","id":"Di toko buku ini banyak dijual buku-buku seperti manga dan novel."}]},{"pattern":"Noun を〜 (Noun wo〜)","meaning":"Indicates the direct object of a verb.","meaningId":"Menunjukkan objek langsung dari kata kerja.","formation":"Noun + を + Verb","formationId":"Kata Benda + を + Kata Kerja","examples":[{"jp":"私は本を読みます。","romaji":"Watashi wa hon wo yomimasu.","en":"I read a book.","id":"Saya membaca buku."},{"jp":"彼はケーキを食べました。","romaji":"Kare wa keeki wo tabemashita.","en":"He ate a cake.","id":"Dia makan kue."},{"jp":"母はコーヒーを飲むのが好きです。","romaji":"Haha wa koohii wo nomu no ga suki desu.","en":"My mother likes to drink coffee.","id":"Ibuku suka minum kopi."},{"jp":"友達が私のペンを使いました。","romaji":"Tomodachi ga watashi no pen wo tsukaimashita.","en":"My friend used my pen.","id":"Teman saya menggunakan pena saya."}]},{"pattern":"Verb た あとで","meaning":"Indicates an action that takes place after another action.","meaningId":"Menunjukkan tindakan yang terjadi setelah tindakan lain.","formation":"Verb-た form + あとで","formationId":"Bentuk kata kerja-た + あとで","examples":[{"jp":"宿題をしたあとで、テレビを見ました。","romaji":"Shukudai wo shita ato de, terebi wo mimashita.","en":"After doing my homework, I watched TV.","id":"Setelah mengerjakan pekerjaan rumah, saya menonton TV."},{"jp":"朝ごはんを食べたあとで、歯を磨きます。","romaji":"Asagohan wo tabeta ato de, ha wo migakimasu.","en":"After eating breakfast, I brush my teeth.","id":"Setelah sarapan, saya menyikat gigi."},{"jp":"仕事が終わったあとで、ジムに行く予定です。","romaji":"Shigoto ga owatta ato de, jimu ni iku yotei desu.","en":"After finishing work, I plan to go to the gym.","id":"Setelah selesai bekerja, saya berencana pergi ke gym."},{"jp":"映画を見たあとで、カフェでコーヒーを飲みました。","romaji":"Eiga wo mita ato de, kafe de koohii wo nomimashita.","en":"After watching the movie, I drank coffee at a cafe.","id":"Setelah menonton film, saya minum kopi di kafe."}]},{"pattern":"Verb たいです","meaning":"Express desire or want to do something; 'I want to', 'I would like to'.","meaningId":"Mengungkapkan keinginan atau keinginan untuk melakukan sesuatu; 'Saya ingin', 'Saya ingin'.","formation":"る-Verb: Remove る and add たいです, う-Verb: Replace the final verb character with the ～い form and add たいです, Exception: する becomes したいです","formationId":"る-Kata Kerja: Hapus る dan tambahkan たいです, う-Kata Kerja: Ganti karakter kata kerja terakhir dengan bentuk ～い dan tambahkan たいです, Pengecualian: する menjadi したいです","examples":[{"jp":"私は寿司を食べたいです。","romaji":"Watashi wa sushi wo tabetai desu.","en":"I want to eat sushi.","id":"Saya ingin makan sushi."},{"jp":"彼は日本に行きたいです。","romaji":"Kare wa Nihon ni ikitai desu.","en":"He wants to go to Japan.","id":"Dia ingin pergi ke Jepang."},{"jp":"彼女は英語を勉強したいです。","romaji":"Kanojo wa eigo wo benkyou shitai desu.","en":"She wants to study English.","id":"Dia ingin belajar bahasa Inggris."},{"jp":"子供たちは遊びたいです。","romaji":"Kodomo-tachi wa asobitai desu.","en":"The children want to play.","id":"Anak-anak ingin bermain."}]},{"pattern":"Verb て～ (Verb + te～)","meaning":"A verb conjugation that connects actions or states.","meaningId":"Konjugasi kata kerja yang menghubungkan tindakan atau keadaan.","formation":"Verb (Group 1) - Replace last syllable with 〜て, Verb (Group 2) - Replace 'る' with 〜て, Verb (Group 3) - する becomes して, くる becomes きて","formationId":"Kata Kerja (Grup 1) - Ganti suku kata terakhir dengan 〜て, Kata Kerja (Grup 2) - Ganti 'る' dengan 〜て, Kata Kerja (Grup 3) - する menjadi して, くる menjadi きて","examples":[{"jp":"コーヒーを飲んで、出かけます。","romaji":"Koohii o nonde, dekakemasu.","en":"After drinking coffee, I will go out.","id":"Setelah minum kopi, saya akan keluar."},{"jp":"買い物をして、家に帰りましょう。","romaji":"Kaimono o shite, ie ni kaerimashou.","en":"Let's go shopping and then go home.","id":"Ayo berbelanja lalu pulang."},{"jp":"宿題をして、寝ます。","romaji":"Shukudai o shite, nemasu.","en":"After doing my homework, I will sleep.","id":"Setelah mengerjakan pekerjaan rumahku, aku akan tidur."},{"jp":"友達を待って、一緒に映画を見に行きます。","romaji":"Tomodachi o matte, issho ni eiga o mini ikimasu.","en":"I will wait for my friend and go watch a movie together.","id":"Saya akan menunggu teman saya dan pergi menonton film bersama."}]},{"pattern":"Verb て います","meaning":"Express ongoing action or state; 'is doing', 'is doing (continuous)', 'has been doing'.","meaningId":"Ekspresikan tindakan atau keadaan yang sedang berlangsung; 'sedang melakukan', 'sedang melakukan (terus menerus)', 'telah melakukan'.","formation":"Verb て-form + います","formationId":"Kata kerja て-bentuk + います","examples":[{"jp":"彼女は今ピアノを弾いています。","romaji":"Kanojo wa ima piano wo hiite imasu.","en":"She is playing the piano now.","id":"Dia sedang bermain piano sekarang."},{"jp":"私たちは日本語を勉強しています。","romaji":"Watashitachi wa nihongo wo benkyou shiteimasu.","en":"We are studying Japanese.","id":"Kami sedang belajar bahasa Jepang."},{"jp":"彼は映画を見ています。","romaji":"Kare wa eiga wo miteimasu.","en":"He is watching a movie.","id":"Dia sedang menonton film."},{"jp":"入っていますので、お待ちください。","romaji":"Haitteimasu node, omachi kudasai.","en":"I am in, so please wait.","id":"Saya ikut, jadi harap tunggu."}]},{"pattern":"Verb てから～ (〜te kara)","meaning":"Express a sequence of actions or events; 'after', 'since', 'once'.","meaningId":"Ekspresikan urutan tindakan atau peristiwa; 'setelah', 'sejak', 'sekali'.","formation":"Verb-て形 + から","formationId":"Kata kerja-て形 + から","examples":[{"jp":"宿題をしてから、テレビを見ました。","romaji":"Shukudai wo shite kara, terebi wo mimashita.","en":"I watched TV after doing my homework.","id":"Saya menonton TV setelah mengerjakan pekerjaan rumah saya."},{"jp":"食べてから、歯を磨きましょう。","romaji":"Tabete kara, ha wo migakimashou.","en":"Let's brush our teeth after eating.","id":"Mari kita gosok gigi setelah makan."},{"jp":"仕事が終わってから、友達と飲みに行きます。","romaji":"Shigoto ga owatte kara, tomodachi to nomi ni ikimasu.","en":"I will go drinking with my friends after work is done.","id":"Saya akan pergi minum dengan teman-teman saya setelah pekerjaan selesai."},{"jp":"学校が終わってから、図書館で勉強します。","romaji":"Gakkou ga owatte kara, toshokan de benkyou shimasu.","en":"I will study in the library after school is over.","id":"Saya akan belajar di perpustakaan setelah sekolah selesai."}]},{"pattern":"Verb て ください (Verb-te kudasai)","meaning":"A request or command; 'please do'.","meaningId":"Permintaan atau perintah; 'tolong lakukan'.","formation":"Verb-て form + ください","formationId":"Bentuk kata kerja-て + ください","examples":[{"jp":"ドアを開けてください。","romaji":"Doa wo akete kudasai.","en":"Please open the door.","id":"Tolong buka pintunya."},{"jp":"電話番号を教えてください。","romaji":"Denwa bangou wo oshiete kudasai.","en":"Please tell me your phone number.","id":"Tolong beritahu saya nomor telepon Anda."},{"jp":"ゆっくり話してください。","romaji":"Yukkuri hanashite kudasai.","en":"Please speak slowly.","id":"Tolong bicara perlahan."},{"jp":"コーヒーを一つ持ってきてください。","romaji":"Koohii wo hitotsu motte kite kudasai.","en":"Please bring me a coffee.","id":"Tolong bawakan aku kopi."}]},{"pattern":"Verb ないで ください (〜naide kudasai)","meaning":"Used to make a polite request for someone not to do something; 'please don't'.","meaningId":"Digunakan untuk mengajukan permintaan sopan kepada seseorang agar tidak melakukan sesuatu; 'tolong jangan'.","formation":"Verb-ない-form + で ください","formationId":"Bentuk kata kerja-ない + で ください","examples":[{"jp":"タバコを吸わないでください。","romaji":"Tabako wo suwanaide kudasai.","en":"Please don't smoke.","id":"Tolong jangan merokok."},{"jp":"ここで走らないでください。","romaji":"Koko de hashiranaide kudasai.","en":"Please don't run here.","id":"Tolong jangan lari ke sini."},{"jp":"大きな声で話さないでください。","romaji":"Ookina koe de hanasanaide kudasai.","en":"Please don't speak loudly.","id":"Tolong jangan bicara keras-keras."},{"jp":"写真を撮らないでください。","romaji":"Shashin wo toranaide kudasai.","en":"Please don't take photos.","id":"Tolong jangan mengambil foto."}]},{"pattern":"Noun に 戻ります","meaning":"Expresses the action of returning to a previous state, place, or condition.","meaningId":"Menyatakan tindakan kembali ke keadaan, tempat, atau kondisi sebelumnya.","formation":"Noun + に + 戻ります","formationId":"Kata Benda + に + 戻ります","examples":[{"jp":"冷蔵庫に入れると、溶けたアイスクリームは固体に戻ります。","romaji":"Reizouko ni ireru to, toketa aisukuriimu wa kotai ni modorimasu.","en":"When put in the refrigerator, the melted ice cream returns to its solid state.","id":"Saat dimasukkan ke dalam lemari es, es krim yang meleleh kembali ke keadaan padatnya."},{"jp":"休暇が終わったら、仕事に戻ります。","romaji":"Kyuuka ga owattara, shigoto ni modorimasu.","en":"When the vacation ends, I will return to work.","id":"Ketika liburan berakhir, saya akan kembali bekerja."},{"jp":"リモートワークが終わった後、元のオフィスに戻ります。","romaji":"Rimooto waaku ga owatta ato, moto no ofisu ni modorimasu.","en":"After remote work is over, we will return to our original office.","id":"Setelah pekerjaan jarak jauh selesai, kami akan kembali ke kantor semula."},{"jp":"外国で勉強した後、日本に帰ります。","romaji":"Gaikoku de benkyou shita ato, Nihon ni kaerimasu.","en":"After studying abroad, I will return to Japan.","id":"Setelah belajar di luar negeri, saya akan kembali ke Jepang."}]},{"pattern":"Verb に 来ます","meaning":"Expresses the purpose of coming to a place; 'come to (do something)'.","meaningId":"Mengungkapkan tujuan datang ke suatu tempat; 'datang untuk (melakukan sesuatu)'.","formation":"Verb (ます-stem) + に + 来ます","formationId":"Kata kerja (ます-batang) + に + 来ます","examples":[{"jp":"友達に会いに来ました。","romaji":"Tomodachi ni ai ni kimashita.","en":"I came to meet my friend.","id":"Saya datang untuk menemui teman saya."},{"jp":"映画を見に来ました。","romaji":"Eiga wo mi ni kimashita.","en":"I came to watch a movie.","id":"Saya datang untuk menonton film."},{"jp":"先生に質問しに来ました。","romaji":"Sensei ni shitsumon shi ni kimashita.","en":"I came to ask the teacher a question.","id":"Saya datang untuk mengajukan pertanyaan kepada guru."},{"jp":"買い物をしに来ました。","romaji":"Kaimono wo shi ni kimashita.","en":"I came to go shopping.","id":"Saya datang untuk pergi berbelanja."}]},{"pattern":"Verb に 行きます","meaning":"To go (somewhere) in order to do an action.","meaningId":"Untuk pergi (ke suatu tempat) untuk melakukan suatu tindakan.","formation":"Verb (ます-stem) + に + 行きます","formationId":"Kata Kerja (ます-batang) + に + 行きます","examples":[{"jp":"公園に遊びに行きます。","romaji":"Kouen ni asobi ni ikimasu.","en":"I will go to the park to play.","id":"Saya akan pergi ke taman untuk bermain."},{"jp":"図書館に勉強しに行きます。","romaji":"Toshokan ni benkyou shi ni ikimasu.","en":"I will go to the library to study.","id":"Saya akan pergi ke perpustakaan untuk belajar."},{"jp":"スーパーに買い物に行きます。","romaji":"Suupaa ni kaimono ni ikimasu.","en":"I will go to the supermarket to do some shopping.","id":"Saya akan pergi ke supermarket untuk berbelanja."},{"jp":"映画館に映画を見に行きます。","romaji":"Eigakan ni eiga wo mi ni ikimasu.","en":"I will go to the movie theater to watch a movie.","id":"Saya akan pergi ke bioskop untuk menonton film."}]},{"pattern":"Verb ましょう","meaning":"Making a suggestion or invitation; 'let's' or 'shall we'.","meaningId":"Membuat saran atau undangan; 'ayo' atau 'haruskah kita'.","formation":"Verb (ます-stem) + ましょう","formationId":"Kata Kerja (ます-batang) + ましょう","examples":[{"jp":"一緒に映画を見ましょう。","romaji":"Issho ni eiga wo mimashou.","en":"Let's watch a movie together.","id":"Mari kita menonton film bersama."},{"jp":"散歩しましょう。","romaji":"Sanpo shimashou.","en":"Let's take a walk.","id":"Ayo jalan-jalan."},{"jp":"今晩、食事に行きましょう。","romaji":"Konban, shokuji ni ikimashou.","en":"Let's go out for dinner tonight.","id":"Ayo pergi makan malam malam ini."},{"jp":"明日勉強しましょう。","romaji":"Ashita benkyou shimashou.","en":"Let's study tomorrow.","id":"Ayo belajar besok."}]},{"pattern":"Verb ましょうか。 (〜mashou ka.)","meaning":"Used to make a polite suggestion or offer help; 'shall we', 'should we', 'do you want me to'.","meaningId":"Digunakan untuk memberikan saran sopan atau menawarkan bantuan; 'haruskah kita', 'haruskah kita', 'apakah kamu ingin aku melakukannya'.","formation":"Verb (ます-stem) + ましょうか","formationId":"Kata kerja (ます-batang) + ましょうか","examples":[{"jp":"一緒に映画を見に行きましょうか。","romaji":"Issho ni eiga wo mi ni ikimashou ka.","en":"Shall we go see a movie together?","id":"Bagaimana kalau kita pergi menonton film bersama?"},{"jp":"コーヒーをもう一杯飲みましょうか。","romaji":"Koohii wo mou ippai nomimashou ka.","en":"Should we have another cup of coffee?","id":"Haruskah kita minum kopi lagi?"},{"jp":"あなたの荷物を持ちましょうか。","romaji":"Anata no nimotsu wo mochimashou ka.","en":"Do you want me to carry your luggage?","id":"Apakah Anda ingin saya membawakan barang bawaan Anda?"},{"jp":"窓を開けましょうか。","romaji":"Mado wo akemashou ka.","en":"Shall I open the window?","id":"Bolehkah aku membuka jendelanya?"}]},{"pattern":"Verb ませんか。 (Verb-masenka)","meaning":"An invitation or suggestion; 'won't you', 'why don't you', 'shall we'.","meaningId":"Undangan atau saran; 'maukah kamu', 'kenapa tidak', 'bolehkah'.","formation":"Verb (ます-form) + ませんか","formationId":"Kata Kerja (ます-bentuk) + ませんか","examples":[{"jp":"一緒に映画を見ませんか。","romaji":"Issho ni eiga wo mimasenka.","en":"Won't you watch a movie together with me?","id":"Maukah kamu menonton film bersama denganku?"},{"jp":"明日のパーティーに参加しませんか。","romaji":"Ashita no paatii ni sanka shimasenka.","en":"Why don't you join tomorrow's party?","id":"Mengapa kamu tidak ikut pesta besok?"},{"jp":"週末にピクニックに行きませんか。","romaji":"Shuumatsu ni pikunikku ni ikimasenka.","en":"Shall we go for a picnic on the weekend?","id":"Bagaimana kalau kita pergi piknik di akhir pekan?"},{"jp":"一緒に勉強しませんか。","romaji":"Issho ni benkyou shimasenka.","en":"How about studying together?","id":"Bagaimana kalau belajar bersama?"}]},{"pattern":"Verb ること～ (〜ru koto)","meaning":"Express an action or event as a noun; 'the act of', 'doing'.","meaningId":"Menyatakan suatu tindakan atau peristiwa sebagai kata benda; 'tindakan', 'melakukan'.","formation":"Verb (dictionary form) + こと","formationId":"Kata kerja (bentuk kamus) + こと","examples":[{"jp":"泳ぐことが大好きです。","romaji":"Oyogu koto ga daisuki desu.","en":"I love swimming.","id":"Saya suka berenang."},{"jp":"日本語を勉強することは楽しいです。","romaji":"Nihongo wo benkyou suru koto wa tanoshii desu.","en":"Studying Japanese is fun.","id":"Belajar bahasa Jepang itu menyenangkan."},{"jp":"友達と話すことがストレスを軽減します。","romaji":"Tomodachi to hanasu koto ga sutoresu wo keigen shimasu.","en":"Talking with friends reduces stress.","id":"Berbicara dengan teman mengurangi stres."},{"jp":"彼は歌うことが得意です。","romaji":"Kare wa utau koto ga tokui desu.","en":"He is good at singing.","id":"Dia pandai menyanyi."}]},{"pattern":"Verb る こと が できます","meaning":"Express the potential form, or the ability to do something.","meaningId":"Mengekspresikan bentuk potensi, atau kemampuan melakukan sesuatu.","formation":"Verb (dictionary form) + ことができます","formationId":"Kata kerja (bentuk kamus) + ことができます","examples":[{"jp":"この問題を解くことができます。","romaji":"Kono mondai o toku koto ga dekimasu.","en":"I can solve this problem.","id":"Saya bisa menyelesaikan masalah ini."},{"jp":"彼は英語を話すことができます。","romaji":"Kare wa eigo o hanasu koto ga dekimasu.","en":"He can speak English.","id":"Dia bisa berbicara bahasa Inggris."},{"jp":"私は高い所に登ることができません。","romaji":"Watashi wa takai tokoro ni noboru koto ga dekimasen.","en":"I can't climb to high places.","id":"Saya tidak bisa mendaki ke tempat yang tinggi."},{"jp":"彼女はピアノを弾くことができます。","romaji":"Kanojo wa piano o hiku koto ga dekimasu.","en":"She can play the piano.","id":"Dia bisa bermain piano."}]},{"pattern":"Verb る こと ができる","meaning":"Expresses the potential form; 'can', 'be able to', 'is possible'.","meaningId":"Mengekspresikan bentuk potensial; 'bisa', 'bisa', 'mungkin'.","formation":"Verb (dictionary form) + ことができる","formationId":"Kata kerja (bentuk kamus) + ことができる","examples":[{"jp":"この問題を解くことができる？","romaji":"Kono mondai o toku koto ga dekiru?","en":"Can you solve this problem?","id":"Bisakah Anda mengatasi masalah ini?"},{"jp":"彼は泳ぐことができます。","romaji":"Kare wa oyogu koto ga dekimasu.","en":"He can swim.","id":"Dia bisa berenang."},{"jp":"日本に行くことができて、とても嬉しいです。","romaji":"Nihon ni iku koto ga dekite, totemo ureshii desu.","en":"I'm very happy that I can go to Japan.","id":"Saya sangat senang bisa pergi ke Jepang."},{"jp":"彼女はピアノを弾くことができます。","romaji":"Kanojo wa piano o hiku koto ga dekimasu.","en":"She can play the piano.","id":"Dia bisa bermain piano."}]},{"pattern":"Verb る の～ (Verb + ru + no~)","meaning":"Used to express the purpose or reason in casual speech, or nominalize the verb with の.","meaningId":"Digunakan untuk mengungkapkan tujuan atau alasan dalam percakapan santai, atau menominasikan kata kerja dengan の.","formation":"Verb (dictionary form) + の (casual)","formationId":"Kata kerja (bentuk kamus) + の (biasa)","examples":[{"jp":"買い物をするために、銀行でお金をおろすの。","romaji":"Kaimono o suru tame ni, ginkou de okane o orosu no.","en":"I'm withdrawing money at the bank so I can go shopping.","id":"Saya menarik uang di bank agar saya bisa berbelanja."},{"jp":"友達にプレゼントをあげるので、ケーキを焼くの。","romaji":"Tomodachi ni purezento o ageru node, keeki o yaku no.","en":"I'm baking a cake because I'm giving my friend a present.","id":"Saya membuat kue karena saya memberikan hadiah kepada teman saya."},{"jp":"ダイエットを始めるので、ジムに入会するの。","romaji":"Daietto o hajimeru node, jimu ni nyuukai suru no.","en":"I’m joining a gym since I'm starting a diet.","id":"Saya bergabung dengan gym sejak saya memulai diet."},{"jp":"軽い食事がいいので、サラダを作るの。","romaji":"Karui shokuji ga ii node, sarada o tsukuru no.","en":"I'm making a salad because I want a light meal.","id":"Saya membuat salad karena saya ingin makanan ringan."}]},{"pattern":"Verb る 前に","meaning":"Used to express 'before' in a sense of an action must be done before another action or event.","meaningId":"Digunakan untuk menyatakan 'sebelum' dalam arti suatu tindakan harus dilakukan sebelum tindakan atau peristiwa lain.","formation":"Verb (dictionary form) + 前に","formationId":"Kata kerja (bentuk kamus) + 前に","examples":[{"jp":"出かける前に、部屋を掃除してください。","romaji":"Dekakeru mae ni, heya o souji shite kudasai.","en":"Please clean the room before leaving.","id":"Harap bersihkan kamar sebelum pergi."},{"jp":"寝る前に、歯を磨きます。","romaji":"Neru mae ni, ha o migakimasu.","en":"I brush my teeth before going to bed.","id":"Saya menyikat gigi sebelum tidur."},{"jp":"雨が降る前に、洗濯物を取り込むこと。","romaji":"Ame ga furu mae ni, sentakumono o torikomu koto.","en":"Take in the laundry before it rains.","id":"Ambil cucian sebelum hujan."},{"jp":"会議が始まる前に、資料を準備しましょう。","romaji":"Kaigi ga hajimaru mae ni, shiryou o junbi shimashou.","en":"Let's prepare the documents before the meeting starts.","id":"Mari kita persiapkan dokumennya sebelum rapat dimulai."}]},{"pattern":"あまり～ありません","meaning":"Express 'not very', 'not much', or 'not really' when describing a negative state or situation.","meaningId":"Ekspresikan 'tidak terlalu', 'tidak banyak', atau 'tidak terlalu' ketika menggambarkan keadaan atau situasi negatif.","formation":"あまり + Verb-ないform + ありません / あまり + い-Adjective-く ありません / あまり + な-Adjective・Noun じゃありません","formationId":"あまり + Kata Kerja-ないbentuk + ありません / あまり + い-Kata Sifat-く ありません / あまり + な-Kata Sifat・Kata Bendaじゃありません","examples":[{"jp":"彼はあまり疲れていません。","romaji":"Kare wa amari tsukareteimasen.","en":"He is not really tired.","id":"Dia tidak terlalu lelah."},{"jp":"彼女はあまり早くないですよ。","romaji":"Kanojo wa amari hayakunai desu yo.","en":"She is not very fast.","id":"Dia tidak terlalu cepat."},{"jp":"私はあまり勉強しないです。","romaji":"Watashi wa amari benkyou shinai desu.","en":"I don't study very much.","id":"Saya tidak belajar banyak."},{"jp":"あまりお金がありません。","romaji":"Amari okane ga arimasen.","en":"I don't have much money.","id":"Saya tidak punya banyak uang."}]},{"pattern":"あまり～ないです","meaning":"Express 'not really' or 'not very'; used to soften a negative statement.","meaningId":"Ekspresikan 'tidak terlalu' atau 'tidak terlalu'; digunakan untuk melunakkan pernyataan negatif.","formation":"あまり + Verb-ないform + です / あまり + い-Adjective-くない + です / あまり + な-Adjective-じゃない + です","formationId":"あまり + Kata Kerja-ないbentuk + です / あまり + い-Kata Sifat-くない + です / あまり + な-Kata Sifat-じゃない + です","examples":[{"jp":"あまり食べないです。","romaji":"Amari tabenai desu.","en":"I don't really eat much.","id":"Aku sebenarnya tidak makan banyak."},{"jp":"この映画はあまり面白くないです。","romaji":"Kono eiga wa amari omoshirokunai desu.","en":"This movie is not really interesting.","id":"Film ini sebenarnya tidak menarik."},{"jp":"彼はあまり親切じゃないです。","romaji":"Kare wa amari shinsetsu ja nai desu.","en":"He is not very kind.","id":"Dia tidak terlalu baik."},{"jp":"私はあまり日本語が上手じゃないです。","romaji":"Watashi wa amari nihongo ga jouzu ja nai desu.","en":"I am not very good at Japanese.","id":"Saya tidak pandai berbahasa Jepang."}]},{"pattern":"～あります (〜arimasu)","meaning":"Indicate possession or existence of inanimate objects; 'there is', 'there are'.","meaningId":"Menunjukkan kepemilikan atau keberadaan benda mati; 'ada', 'ada'.","formation":"Object + が + あります","formationId":"Objek + が + あります","examples":[{"jp":"教室に机があります。","romaji":"Kyoushitsu ni tsukue ga arimasu.","en":"There is a desk in the classroom.","id":"Ada meja di dalam kelas."},{"jp":"この公園にたくさんの花があります。","romaji":"Kono kouen ni takusan no hana ga arimasu.","en":"There are many flowers in this park.","id":"Ada banyak bunga di taman ini."},{"jp":"駅の近くにコンビニがあります。","romaji":"Eki no chikaku ni konbini ga arimasu.","en":"There is a convenience store near the station.","id":"Ada toko serba ada di dekat stasiun."},{"jp":"家の中に古いテレビがあります。","romaji":"Ie no naka ni furui terebi ga arimasu.","en":"There is an old TV inside the house.","id":"Ada TV tua di dalam rumah."}]},{"pattern":"～いかがですか。 (〜ikaga desu ka.)","meaning":"A polite way to ask someone's thoughts, opinions, or preferences; 'how about', 'how is'.","meaningId":"Cara sopan untuk menanyakan pemikiran, pendapat, atau preferensi seseorang; 'bagaimana', 'bagaimana'.","formation":"Noun + は + いかがですか / (Verb-て form + は) いかがですか","formationId":"Kata benda + は + いかがですか / (Bentuk kata kerja-て + は) いかがですか","examples":[{"jp":"お茶はいかがですか？","romaji":"Ocha wa ikaga desu ka?","en":"How about some tea?","id":"Bagaimana kalau minum teh?"},{"jp":"このドレスはいかがですか？","romaji":"Kono doresu wa ikaga desu ka?","en":"How about this dress?","id":"Bagaimana dengan gaun ini?"},{"jp":"ケーキを食べてはいかがですか？","romaji":"Keeki wo tabete wa ikaga desu ka?","en":"How about eating some cake?","id":"Bagaimana kalau makan kue?"},{"jp":"映画を見てはいかがですか？","romaji":"Eiga wo mite wa ikaga desu ka?","en":"How about watching a movie?","id":"Bagaimana kalau menonton film?"}]},{"pattern":"いくつ～","meaning":"Used to express 'how many' or ask for the number of something.","meaningId":"Digunakan untuk menyatakan 'berapa banyak' atau menanyakan nomor sesuatu.","formation":"いくつ + Noun (optional)","formationId":"いくつ + Kata Benda (opsional)","examples":[{"jp":"リンゴはいくつありますか？","romaji":"Ringo wa ikutsu arimasu ka?","en":"How many apples are there?","id":"Berapa banyak apel yang ada di sana?"},{"jp":"いくつかの問題を解決しなければなりません。","romaji":"Ikutsu ka no mondai o kaiketsu shinakereba narimasen.","en":"I have to solve several problems.","id":"Saya harus menyelesaikan beberapa masalah."},{"jp":"あなたはいくつの言語を話せますか？","romaji":"Anata wa ikutsu no gengo o hanasemasu ka?","en":"How many languages can you speak?","id":"Berapa banyak bahasa yang bisa Anda kuasai?"},{"jp":"パーティーにはいくつかの飲み物があります。","romaji":"Paatii ni wa ikutsu ka no nomimono ga arimasu.","en":"There are several drinks at the party.","id":"Ada beberapa minuman di pesta itu."}]},{"pattern":"いつか～","meaning":"Indicates an unspecified point in time; 'someday', 'one day', 'at some point'.","meaningId":"Menunjukkan titik waktu yang tidak ditentukan; 'suatu hari nanti', 'suatu hari', 'pada suatu saat'.","formation":"いつか + sentence","formationId":"いつか + kalimat","examples":[{"jp":"いつか日本に行きたいです。","romaji":"Itsuka Nihon ni ikitai desu.","en":"I want to go to Japan someday.","id":"Saya ingin pergi ke Jepang suatu hari nanti."},{"jp":"彼はいつか有名な作家になるでしょう。","romaji":"Kare wa itsuka yuumei na sakka ni naru deshou.","en":"He will become a famous writer someday.","id":"Dia akan menjadi penulis terkenal suatu hari nanti."},{"jp":"いつかあの山を登りたいと思っています。","romaji":"Itsuka ano yama wo noboritai to omotte imasu.","en":"I think I want to climb that mountain someday.","id":"Saya rasa saya ingin mendaki gunung itu suatu hari nanti."},{"jp":"彼女はいつか夢を叶えることができると信じています。","romaji":"Kanojo wa itsuka yume wo kanaeru koto ga dekiru to shinjiteimasu.","en":"I believe she can achieve her dream someday.","id":"Saya percaya dia bisa mencapai mimpinya suatu hari nanti."}]},{"pattern":"いつでも～","meaning":"Expresses 'anytime', 'always', or 'whenever'.","meaningId":"Menyatakan 'kapan saja', 'selalu', atau 'kapan saja'.","formation":"いつでも + (Verb)","formationId":"いつでも + (Kata kerja)","examples":[{"jp":"いつでも遊びに来てください。","romaji":"Itsudemo asobi ni kite kudasai.","en":"Please come to play anytime.","id":"Silakan datang untuk bermain kapan saja."},{"jp":"彼女はいつでも笑顔です。","romaji":"Kanojo wa itsudemo egao desu.","en":"She is always smiling.","id":"Dia selalu tersenyum."},{"jp":"いつでも電話で連絡できます。","romaji":"Itsudemo denwa de renraku dekimasu.","en":"You can contact me by phone anytime.","id":"Anda bisa menghubungi saya melalui telepon kapan saja."},{"jp":"この店はいつでも混んでいます。","romaji":"Kono mise wa itsudemo konde imasu.","en":"This store is always crowded.","id":"Toko ini selalu ramai."}]},{"pattern":"いつも～","meaning":"Expressing 'always' or 'usually' in a sentence.","meaningId":"Mengekspresikan 'selalu' atau 'biasanya' dalam sebuah kalimat.","formation":"いつも + Verb / Adjective / Noun","formationId":"いつも + Kata Kerja / Kata Sifat / Kata Benda","examples":[{"jp":"彼はいつも遅刻します。","romaji":"Kare wa itsumo chikoku shimasu.","en":"He is always late.","id":"Dia selalu terlambat."},{"jp":"私はいつも優しい犬が好きです。","romaji":"Watashi wa itsumo yasashii inu ga suki desu.","en":"I always like gentle dogs.","id":"Saya selalu menyukai anjing yang lembut."},{"jp":"彼女はいつも静かな場所で勉強します。","romaji":"Kanojo wa itsumo shizuka na basho de benkyou shimasu.","en":"She always studies in a quiet place.","id":"Dia selalu belajar di tempat yang tenang."},{"jp":"いつも朝ご飯を食べます。","romaji":"Itsumo asagohan wo tabemasu.","en":"I always eat breakfast.","id":"Saya selalu sarapan."}]},{"pattern":"～て います","meaning":"Expresses the present continuous or ongoing action; 'to be doing', 'currently doing'.","meaningId":"Mengekspresikan tindakan yang sedang berlangsung atau sedang berlangsung; 'sedang melakukan', 'sedang melakukan'.","formation":"Verb て-form + います","formationId":"Kata kerja て-bentuk + います","examples":[{"jp":"今、音楽を聞いています。","romaji":"Ima, ongaku wo kiite imasu.","en":"I am listening to music right now.","id":"Saya sedang mendengarkan musik sekarang."},{"jp":"父は新聞を読んでいます。","romaji":"Chichi wa shinbun wo yonde imasu.","en":"My father is reading a newspaper.","id":"Ayah saya sedang membaca koran."},{"jp":"彼女は英語を勉強しています。","romaji":"Kanojo wa eigo wo benkyou shite imasu.","en":"She is studying English.","id":"Dia sedang belajar bahasa Inggris."},{"jp":"子供たちは公園で遊んでいます。","romaji":"Kodomotachi wa kouen de asonde imasu.","en":"The children are playing in the park.","id":"Anak-anak sedang bermain di taman."}]},{"pattern":"～が (〜ga)","meaning":"Particle indicating the subject of a sentence or expressing 'but'.","meaningId":"Partikel yang menunjukkan subjek kalimat atau menyatakan 'tetapi'.","formation":"Noun + が / い-Adjective + が / な-Adjective + が / Verb + が","formationId":"Kata Benda + が / い-Kata Sifat + が / な-Kata Sifat + が / Kata Kerja + が","examples":[{"jp":"私が学生です。","romaji":"Watashi ga gakusei desu.","en":"I am a student.","id":"Saya pelajar."},{"jp":"このりんごが美味しい。","romaji":"Kono ringo ga oishii.","en":"This apple is delicious.","id":"Apel ini enak."},{"jp":"彼は頭がいいが、性格が悪い。","romaji":"Kare wa atama ga ii ga, seikaku ga warui.","en":"He is smart but has a bad personality.","id":"Dia pintar tetapi memiliki kepribadian yang buruk."},{"jp":"走りたいが、足が痛い。","romaji":"Hashiritai ga, ashi ga itai.","en":"I want to run, but my leg hurts.","id":"Aku ingin lari, tapi kakiku sakit."}]},{"pattern":"～が、～ (〜ga, 〜)","meaning":"Express a contrast between two sentences; 'but', 'however'.","meaningId":"Ekspresikan kontras antara dua kalimat; 'tapi', 'namun'.","formation":"Sentence 1 + が、+ Sentence 2","formationId":"Kalimat 1 + が、+ Kalimat 2","examples":[{"jp":"デザートは美味しいが、カロリーが高い。","romaji":"Dezaato wa oishii ga, karorii ga takai.","en":"The dessert is delicious, but it is high in calories.","id":"Makanan penutupnya enak, tapi tinggi kalori."},{"jp":"彼は頭がいいが、少し怠け者だ。","romaji":"Kare wa atama ga ii ga, sukoshi namakemono da.","en":"He is smart, but a bit lazy.","id":"Dia pintar, tapi agak malas."},{"jp":"会社は利益を上げたが、従業員の給与は上がらなかった。","romaji":"Kaisha wa rieki wo ageta ga, juugyouin no kyuuyo wa agaranakatta.","en":"The company made a profit, however, the employees' salaries did not increase.","id":"Perusahaan mendapat untung, namun gaji karyawan tidak bertambah."},{"jp":"外国語を勉強することが楽しいが、時々難しい。","romaji":"Gaikokugo wo benkyou suru koto ga tanoshii ga, tokidoki muzukashii.","en":"Studying foreign languages is fun, but sometimes difficult.","id":"Mempelajari bahasa asing memang menyenangkan, namun terkadang sulit."}]},{"pattern":"～から、～ (〜kara、～)","meaning":"Expresses reason or cause; 'because', 'since', 'so'.","meaningId":"Mengungkapkan alasan atau sebab; 'karena', 'sejak', 'jadi'.","formation":"Verb-casual + から / い-Adjective + から / な-Adjective + だから / Noun + だから","formationId":"Kata Kerja-kasual + から / い-Kata Sifat + から / な-Kata Sifat + だから / Kata Benda + だから","examples":[{"jp":"明日は試験があるから、今晩勉強しなければなりません。","romaji":"Ashita wa shiken ga aru kara, konban benkyou shinakereba narimasen.","en":"Because I have an exam tomorrow, I must study tonight.","id":"Karena besok aku ada ujian, aku harus belajar malam ini."},{"jp":"この部屋は狭いから、もっと大きい部屋を探しています。","romaji":"Kono heya wa semai kara, motto ookii heya wo sagashiteimasu.","en":"Since this room is small, I am looking for a bigger one.","id":"Karena ruangan ini kecil, saya mencari yang lebih besar."},{"jp":"彼は友達だから、手伝ってくれるでしょう。","romaji":"Kare wa tomodachi dakara, tetsudatte kureru deshou.","en":"Since he is my friend, he will probably help me.","id":"Karena dia adalah temanku, dia mungkin akan membantuku."},{"jp":"雨が降ったから、外に出られません。","romaji":"Ame ga futta kara, soto ni deraremasen.","en":"Because it rained, I can't go outside.","id":"Karena hujan, saya tidak bisa keluar."}]},{"pattern":"～からです (〜kara desu)","meaning":"Express the reason or cause; 'because', 'since', 'due to'.","meaningId":"Nyatakan alasan atau penyebabnya; 'karena', 'sejak', 'karena'.","formation":"Verb-casual + からです / い-Adjective + からです / な-Adjective + だからです / Noun + だからです","formationId":"Kata Kerja-kasual + からです / い-Kata Sifat + からです / な-Kata Sifat + だからです / Kata Benda + だからです","examples":[{"jp":"寒いからです。コートを着ています。","romaji":"Samui kara desu. Kooto wo kiteimasu.","en":"It’s because it’s cold. That’s why I’m wearing a coat.","id":"Itu karena cuacanya dingin. Itu sebabnya saya memakai mantel."},{"jp":"この店は安いからです。よく来ます。","romaji":"Kono mise wa yasui kara desu. Yoku kimasu.","en":"It’s because this store is cheap. That’s why I come often.","id":"Itu karena toko ini murah. Itu sebabnya saya sering datang."},{"jp":"彼は親切だからです。みんなに好かれています。","romaji":"Kare wa shinsetsu dakara desu. Minna ni suka-rete imasu.","en":"It’s because he’s kind. Everyone likes him.","id":"Itu karena dia baik hati. Semua orang menyukainya."},{"jp":"彼女は学生だからです。図書館で勉強しています。","romaji":"Kanojo wa gakusei dakara desu. Toshokan de benkyou shiteimasu.","en":"It’s because she’s a student. She studies at the library.","id":"Itu karena dia seorang pelajar. Dia belajar di perpustakaan."}]},{"pattern":"～から もらいます (〜kara moraimasu)","meaning":"To receive something or get someone to do something.","meaningId":"Untuk menerima sesuatu atau membuat seseorang melakukan sesuatu.","formation":"Noun + から + (Verb-て form) + もらいます","formationId":"Kata benda + から + (Bentuk kata kerja-て) + もらいます","examples":[{"jp":"友達からプレゼントをもらいました。","romaji":"Tomodachi kara purezento wo moraimashita.","en":"I received a present from my friend.","id":"Aku menerima hadiah dari temanku."},{"jp":"先生に宿題を渡してもらいました。","romaji":"Sensei ni shukudai wo watashite moraimashita.","en":"I had the teacher hand me the homework.","id":"Saya meminta guru memberi saya pekerjaan rumah."},{"jp":"お母さんに料理を作ってもらいました。","romaji":"Okaasan ni ryouri wo tsukutte moraimashita.","en":"I got my mom to cook for me.","id":"Aku menyuruh ibuku memasak untukku."},{"jp":"兄に車を貸してもらいました。","romaji":"Ani ni kuruma wo kashite moraimashita.","en":"I got my older brother to lend me his car.","id":"Saya meminta kakak laki-laki saya untuk meminjamkan mobilnya kepada saya."}]},{"pattern":"～が 私に くれます (〜ga watashi ni kuremasu)","meaning":"Used to express that someone gives a gift or favor to 'me'; 'someone gives me'.","meaningId":"Digunakan untuk menyatakan bahwa seseorang memberikan hadiah atau bantuan kepada 'saya'; 'seseorang memberiku'.","formation":"Person + が + (Thing or Action) + 私に + くれます","formationId":"Orang + が + (Benda atau Tindakan) + 私に + くれます","examples":[{"jp":"彼がプレゼントを私にくれました。","romaji":"Kare ga purezento wo watashi ni kuremashita.","en":"He gave me a present.","id":"Dia memberiku hadiah."},{"jp":"友達が宿題を手伝って私にくれました。","romaji":"Tomodachi ga shukudai wo tetsudatte watashi ni kuremashita.","en":"My friend helped me with my homework.","id":"Teman saya membantu saya mengerjakan pekerjaan rumah saya."},{"jp":"お母さんがお弁当を作って私にくれました。","romaji":"Okaasan ga obentou wo tsukutte watashi ni kuremashita.","en":"My mom made me a lunch box.","id":"Ibuku membuatkanku kotak makan siang."},{"jp":"先生がアドバイスを私にくれました。","romaji":"Sensei ga adobaisu wo watashi ni kuremashita.","en":"The teacher gave me advice.","id":"Guru memberi saya nasihat."}]},{"pattern":"～けど、～ (〜kedo、～)","meaning":"Used to connect two clauses; 'but', 'however', 'although'","meaningId":"Digunakan untuk menghubungkan dua klausa; 'tetapi', 'namun', 'walaupun'","formation":"Verb-casual + けど / い-adjective + けど / な-adjective + だけど / Noun + だけど","formationId":"Kata kerja-kasual + けど / い-kata sifat + けど / な-kata sifat + だけど / Kata benda + だけど","examples":[{"jp":"授業に出たけど、まだ宿題をしないといけない。","romaji":"Jugyou ni deta kedo, mada shukudai wo shinai to ikenai.","en":"I attended the class, but I still have to do my homework.","id":"Saya menghadiri kelas, tetapi saya masih harus mengerjakan pekerjaan rumah saya."},{"jp":"昨日寒かったけど、今日は暖かいです。","romaji":"Kinou samukatta kedo, kyou wa atatakai desu.","en":"Yesterday was cold, but today is warm.","id":"Kemarin dingin, tapi hari ini hangat."},{"jp":"彼は親切だけど、ちょっと怖い。","romaji":"Kare wa shinsetsu da kedo, chotto kowai.","en":"He is kind, but a little scary.","id":"Dia baik, tapi sedikit menakutkan."},{"jp":"これはおいしそうだけど、高すぎる。","romaji":"Kore wa oishisou da kedo, takasugiru.","en":"This looks delicious, but it is too expensive.","id":"Kelihatannya enak, tapi harganya terlalu mahal."}]},{"pattern":"～けれど、～ (〜keredo、～)","meaning":"Expresses a contrast or contradiction; 'but', 'however', 'even though'.","meaningId":"Mengekspresikan kontras atau kontradiksi; 'tetapi', 'namun', 'meskipun'.","formation":"Verb-casual + けれど / い-Adjective + けれど / な-Adjective + だけれど / Noun + だけれど","formationId":"Kata Kerja-kasual + けれど / い-Kata Sifat + けれど / な-Kata Sifat + だけれど / Kata Benda + だけれど","examples":[{"jp":"今日は寒いけれど、散歩に行きます。","romaji":"Kyou wa samui keredo, sanpo ni ikimasu.","en":"Even though it's cold today, I'll go for a walk.","id":"Meskipun hari ini dingin, aku akan pergi jalan-jalan."},{"jp":"彼は親切けれど、少し怖いです。","romaji":"Kare wa shinsetsu keredo, sukoshi kowai desu.","en":"He is kind, but a little scary.","id":"Dia baik, tapi sedikit menakutkan."},{"jp":"この部屋は狭いけれど、明るいです。","romaji":"Kono heya wa semai keredo, akarui desu.","en":"This room is small, but it's bright.","id":"Ruangan ini kecil, tapi terang."},{"jp":"彼女は病気だけれど、毎日働いています。","romaji":"Kanojo wa byouki dakeredo, mainichi hataraite imasu.","en":"She is sick, but she works every day.","id":"Dia sakit, tapi dia bekerja setiap hari."}]},{"pattern":"こちら～","meaning":"Refers to a person, place or thing; 'this', 'this one', 'this way', 'here'.","meaningId":"Mengacu pada seseorang, tempat atau benda; 'ini', 'yang ini', 'sebelah sini', 'di sini'.","formation":"こちら / こちら + の + Person/Thing","formationId":"こちら / こちら + の + Orang/Benda","examples":[{"jp":"こちらは田中さんです。","romaji":"Kochira wa Tanaka-san desu.","en":"This is Mr./Ms. Tanaka.","id":"Ini Tuan/Ibu. Tanaka."},{"jp":"こちらのレストランは美味しいです。","romaji":"Kochira no resutoran wa oishii desu.","en":"This restaurant is delicious.","id":"Restoran ini enak."},{"jp":"こちらへどうぞ。","romaji":"Kochira e douzo.","en":"Please come this way.","id":"Silakan lewat sini."},{"jp":"こちらの方がいいですか、それともあちらの方がいいですか？","romaji":"Kochira no hou ga ii desu ka, sore to mo achira no hou ga ii desu ka?","en":"Is this one better, or is that one better?","id":"Apakah yang ini lebih baik, atau yang itu lebih baik?"}]},{"pattern":"さっき～","meaning":"Refers to a short time ago or just now.","meaningId":"Mengacu pada beberapa waktu yang lalu atau baru saja.","formation":"さっき + verb / さっき + phrase","formationId":"さっき + kata kerja / さっき + frasa","examples":[{"jp":"さっき電話がありました。","romaji":"Sakki denwa ga arimashita.","en":"There was a phone call just now.","id":"Ada panggilan telepon tadi."},{"jp":"さっき部屋を掃除しました。","romaji":"Sakki heya wo souji shimashita.","en":"I cleaned the room a short while ago.","id":"Saya membersihkan kamar beberapa waktu yang lalu."},{"jp":"さっき彼に会いました。","romaji":"Sakki kare ni aimashita.","en":"I met him just now.","id":"Saya baru saja bertemu dengannya."},{"jp":"さっきのニュースを見ましたか？","romaji":"Sakki no nyuusu wo mimashita ka?","en":"Did you watch the news a short time ago?","id":"Apakah Anda menonton berita beberapa waktu yang lalu?"}]},{"pattern":"すぐに～","meaning":"Immediately or right away; used to express promptness or quickness.","meaningId":"Segera atau segera; digunakan untuk menyatakan ketepatan atau kecepatan.","formation":"すぐに + Verb/Adjective","formationId":"すぐに + Kata Kerja/Kata Sifat","examples":[{"jp":"友達が来たら、すぐに電話をかけてください。","romaji":"Tomodachi ga kitara, sugu ni denwa wo kakete kudasai.","en":"When my friend arrives, please call me right away.","id":"Ketika teman saya tiba, tolong segera hubungi saya."},{"jp":"そのニュースを聞いたら、すぐに会社に行きました。","romaji":"Sono nyuusu wo kiitara, sugu ni kaisha ni ikimashita.","en":"Upon hearing that news, I went to the company immediately.","id":"Mendengar berita itu, saya segera pergi ke perusahaan."},{"jp":"彼女はすぐに泣き出した。","romaji":"Kanojo wa sugu ni nakidashita.","en":"She started crying right away.","id":"Dia langsung menangis."},{"jp":"教室に入ると、先生はすぐに授業を始めた。","romaji":"Kyoushitsu ni hairu to, sensei wa sugu ni jugyou wo hajimeta.","en":"As soon as I entered the classroom, the teacher started the lesson immediately.","id":"Begitu saya memasuki kelas, guru segera memulai pelajaran."}]},{"pattern":"ぜんぜん～","meaning":"Used to express 'not at all' or 'completely' in negative sentences.","meaningId":"Digunakan untuk menyatakan 'tidak sama sekali' atau 'sepenuhnya' dalam kalimat negatif.","formation":"ぜんぜん + [Negative verb/adjective]","formationId":"ぜんぜん + [Kata kerja/kata sifat negatif]","examples":[{"jp":"彼はぜんぜん話さない。","romaji":"Kare wa zenzen hanasanai.","en":"He doesn't talk at all.","id":"Dia tidak berbicara sama sekali."},{"jp":"この部屋はぜんぜん暗くない。","romaji":"Kono heya wa zenzen kurakunai.","en":"This room is not dark at all.","id":"Ruangan ini sama sekali tidak gelap."},{"jp":"彼女はぜんぜん疲れていない。","romaji":"Kanojo wa zenzen tsukarete inai.","en":"She is not tired at all.","id":"Dia tidak lelah sama sekali."},{"jp":"その映画はぜんぜん面白くなかった。","romaji":"Sono eiga wa zenzen omoshirokunakatta.","en":"That movie was not interesting at all.","id":"Film itu sama sekali tidak menarik."}]},{"pattern":"そして、～ (soshite、～)","meaning":"Used to connect two sentences; 'and then', 'and'.","meaningId":"Digunakan untuk menghubungkan dua kalimat; 'lalu', 'dan'.","formation":"Sentence 1 + そして + Sentence 2","formationId":"Kalimat 1 + そして + Kalimat 2","examples":[{"jp":"朝起きて、そして宿題をしました。","romaji":"Asa okite, soshite shukudai wo shimashita.","en":"I woke up in the morning and then did my homework.","id":"Saya bangun di pagi hari dan kemudian mengerjakan pekerjaan rumah saya."},{"jp":"コーヒーを飲んで、そして新聞を読みました。","romaji":"Koohii wo nonde, soshite shinbun wo yomimashita.","en":"I drank coffee and then read the newspaper.","id":"Saya minum kopi dan kemudian membaca koran."},{"jp":"家を出発しました。そして、駅へ行きました。","romaji":"Ie wo shuppatsu shimashita. Soshite, eki e ikimashita.","en":"I left my house and then went to the station.","id":"Aku meninggalkan rumahku lalu pergi ke stasiun."},{"jp":"彼はゲームをした。そして、テレビを見ました。","romaji":"Kare wa geemu wo shita. Soshite, terebi wo mimashita.","en":"He played games and then watched TV.","id":"Dia bermain game dan kemudian menonton TV."}]},{"pattern":"そちら～","meaning":"Indicates a direction or person in moderate distance; 'that way', 'that person'.","meaningId":"Menunjukkan arah atau orang dalam jarak sedang; 'ke sana', 'orang itu'.","formation":"そちら [alone] / そちら + の + Noun","formationId":"そちら [sendirian] / そちら + の + Kata Benda","examples":[{"jp":"そちらのレストランはどうですか？","romaji":"Sochira no resutoran wa dou desu ka?","en":"How is that restaurant over there?","id":"Bagaimana restoran di sana itu?"},{"jp":"そちらの方、お名前を教えていただけますか？","romaji":"Sochira no kata, onamae o oshiete itadakemasu ka?","en":"Could you tell me the name of that person over there?","id":"Bisakah Anda memberi tahu saya nama orang di sana itu?"},{"jp":"そちらに行く途中で駅があります。","romaji":"Sochira ni iku tochuu de eki ga arimasu.","en":"There is a station on the way to that direction.","id":"Ada stasiun dalam perjalanan ke arah itu."},{"jp":"そちらのかばん、私のと似ていますね。","romaji":"Sochira no kaban, watashi no to niteimasu ne.","en":"That bag over there looks similar to mine.","id":"Tas di sana itu mirip dengan milikku."}]},{"pattern":"それから、～ (sorekara、～)","meaning":"Meaning 'after that', 'and then' or 'then', indicating sequence of events.","meaningId":"Artinya 'setelah itu', 'dan kemudian' atau 'kemudian', menunjukkan urutan kejadian.","formation":"Clause 1 + それから + Clause 2","formationId":"Klausul 1 + それから + Klausul 2","examples":[{"jp":"コーヒーを飲んで、それから家を出ました。","romaji":"Koohii o nonde, sorekara ie o demashita.","en":"I drank coffee, and then I left the house.","id":"Saya minum kopi, lalu meninggalkan rumah."},{"jp":"買い物をして、それから映画を見に行きました。","romaji":"Kaimono o shite, sorekara eiga o mini ikimashita.","en":"I went shopping, and then I went to watch a movie.","id":"Saya pergi berbelanja, dan kemudian saya pergi menonton film."},{"jp":"彼女は勉強をして、それから寝ました。","romaji":"Kanojo wa benkyou o shite, sorekara nemashita.","en":"She studied, and then she went to sleep.","id":"Dia belajar, lalu dia pergi tidur."},{"jp":"パーティーに行って、それから友達と話しました。","romaji":"Paatii ni itte, sorekara tomodachi to hanashimashita.","en":"I went to the party, and then I talked with my friends.","id":"Saya pergi ke pesta, dan kemudian saya berbicara dengan teman-teman saya."}]},{"pattern":"だいたい〜 (daitai〜)","meaning":"Expresses 'roughly', 'approximately', or 'almost'.","meaningId":"Menyatakan 'kira-kira', 'kira-kira', atau 'hampir'.","formation":"だいたい + Number/Amount/Percentage","formationId":"だいたい + Angka/Jumlah/Persentase","examples":[{"jp":"だいたい１００人がパーティーに参加しました。","romaji":"Daitai hyaku-nin ga paatii ni sanka shimashita.","en":"Approximately 100 people attended the party.","id":"Sekitar 100 orang menghadiri pesta tersebut."},{"jp":"彼女はだいたい２時間でその仕事を終えます。","romaji":"Kanojo wa daitai ni-jikan de sono shigoto o oemasu.","en":"She finishes that work in roughly two hours.","id":"Dia menyelesaikan pekerjaan itu dalam waktu sekitar dua jam."},{"jp":"だいたい８０％の生徒が試験に合格しました。","romaji":"Daitai hachijuu-paasento no seito ga shiken ni goukaku shimashita.","en":"About 80% of the students passed the exam.","id":"Sekitar 80% siswa lulus ujian."},{"jp":"今日はだいたい３０度の暑さです。","romaji":"Kyou wa daitai sanjuu-do no atsusa desu.","en":"Today is almost 30 degrees hot.","id":"Hari ini suhunya hampir 30 derajat."}]},{"pattern":"たいてい～","meaning":"Used for expressing 'usually', 'mostly', or 'generally'.","meaningId":"Digunakan untuk menyatakan 'biasanya', 'sebagian besar', atau 'umumnya'.","formation":"たいてい + Verb/い-Adjective/な-Adjective/Noun","formationId":"たいてい + Kata Kerja/い-Kata Sifat/な-Kata Sifat/Kata Benda","examples":[{"jp":"たいてい朝８時に起きます。","romaji":"Taitei asa hachi-ji ni okimasu.","en":"I usually wake up at 8 o'clock in the morning.","id":"Saya biasanya bangun jam 8 pagi."},{"jp":"彼はたいてい遅刻します。","romaji":"Kare wa taitei chikoku shimasu.","en":"He is usually late.","id":"Dia biasanya terlambat."},{"jp":"この店の商品はたいてい安いです。","romaji":"Kono mise no shouhin wa taitei yasui desu.","en":"The items at this store are usually cheap.","id":"Barang-barang di toko ini biasanya murah."},{"jp":"たいていの人はその映画が好きです。","romaji":"Taitei no hito wa sono eiga ga suki desu.","en":"Most people like that movie.","id":"Kebanyakan orang menyukai film itu."}]},{"pattern":"だから、～ (dakara、～)","meaning":"Expresses a reason or cause; 'because', 'so', 'therefore'.","meaningId":"Mengungkapkan alasan atau sebab; 'karena', 'jadi', 'oleh karena itu'.","formation":"Noun + だから / な-Adjective + だから","formationId":"Kata Benda + だから / な-Kata Sifat + だから","examples":[{"jp":"雨だから、傘を持って行きましょう。","romaji":"Ame dakara, kasa wo motte ikimashou.","en":"Because it's raining, let's bring an umbrella.","id":"Karena hujan, ayo bawa payung."},{"jp":"このケーキは有名だから、みんなが食べたいです。","romaji":"Kono keeki wa yuumei dakara, minna ga tabetai desu.","en":"Because this cake is famous, everyone wants to eat it.","id":"Karena kue ini terkenal, semua orang ingin memakannya."},{"jp":"彼は病気だから、学校に行けません。","romaji":"Kare wa byouki dakara, gakkou ni ikemasen.","en":"Because he is sick, he cannot go to school.","id":"Karena dia sakit, dia tidak bisa bersekolah."},{"jp":"彼女は学生だから、このレストランで割引があります。","romaji":"Kanojo wa gakusei dakara, kono resutoran de waribiki ga arimasu.","en":"Because she is a student, there is a discount at this restaurant.","id":"Karena dia pelajar, ada diskon di restoran ini."}]},{"pattern":"～たり、～たり します (〜tari, 〜tari shimasu)","meaning":"Used to list multiple actions or states; 'do things like', 'and'.","meaningId":"Digunakan untuk mencantumkan beberapa tindakan atau status; 'melakukan hal-hal seperti', 'dan'.","formation":"Verb-casual-past + たり + Verb-casual-past + たり + します","formationId":"Kata kerja-santai-masa lalu + たり + Kata kerja-masa lalu-santai + たり + します","examples":[{"jp":"休日には、映画を見たり、友達と遊んだりします。","romaji":"Kyuujitsu ni wa, eiga wo mitari, tomodachi to asondari shimasu.","en":"On holidays, I do things like watch movies and hang out with friends.","id":"Pada hari libur, saya melakukan hal-hal seperti menonton film dan berkumpul dengan teman-teman."},{"jp":"彼は歌ったり、踊ったり、ピアノを弾いたりします。","romaji":"Kare wa utattari, odottari, piano wo hikitari shimasu.","en":"He sings, dances, plays the piano, among other things.","id":"Dia menyanyi, menari, bermain piano, dan lain-lain."},{"jp":"このレストランでは、寿司を食べたり、刺身を食べたりします。","romaji":"Kono resutoran de wa, sushi wo tabetari, sashimi wo tabetari shimasu.","en":"At this restaurant, you can eat sushi, sashimi, and so on.","id":"Di restoran ini, Anda bisa menyantap sushi, sashimi, dan lain sebagainya."},{"jp":"彼女は毎朝、ジョギングしたり、ヨガをしたりします。","romaji":"Kanojo wa maiasa, joggingu shitari, yoga wo shitari shimasu.","en":"Every morning, she does things like jogging and yoga.","id":"Setiap pagi, dia melakukan hal-hal seperti jogging dan yoga."}]},{"pattern":"だれ～","meaning":"Asking 'who' in a sentence, used to inquire about someone's identity or to clarify who is being referred to.","meaningId":"Menanyakan 'siapa' dalam sebuah kalimat, digunakan untuk menanyakan identitas seseorang atau untuk memperjelas siapa yang dimaksud.","formation":"だれ + appropriate particle (が, は or を)","formationId":"だれ + partikel yang sesuai (が, は atau を)","examples":[{"jp":"だれがその本を買いましたか。","romaji":"Dare ga sono hon o kaimashita ka.","en":"Who bought that book?","id":"Siapa yang membeli buku itu?"},{"jp":"だれを待っていますか。","romaji":"Dare o matteimasu ka.","en":"Whom are you waiting for?","id":"Siapa yang kamu tunggu?"},{"jp":"だれがそのリンゴを食べましたか。","romaji":"Dare ga sono ringo o tabemashita ka.","en":"Who ate that apple?","id":"Siapa yang memakan apel itu?"},{"jp":"だれが鍵を持っていますか。","romaji":"Dare ga kagi o motteimasu ka.","en":"Who has the key?","id":"Siapa yang punya kuncinya?"}]},{"pattern":"だれか〜 (dareka〜)","meaning":"Indicates 'someone' or something done or possessed by 'someone'.","meaningId":"Menunjukkan 'seseorang' atau sesuatu yang dilakukan atau dimiliki oleh 'seseorang'.","formation":"だれか + Verb, だれか + Adjective, だれか + Noun","formationId":"だれか + Kata Kerja, だれか + Kata Sifat, だれか + Kata Benda","examples":[{"jp":"だれかがドアをノックしました。","romaji":"Dareka ga doa wo nokku shimashita.","en":"Someone knocked on the door.","id":"Seseorang mengetuk pintu."},{"jp":"だれかが私の傘を盗みました。","romaji":"Dareka ga watashi no kasa wo nusumimashita.","en":"Someone stole my umbrella.","id":"Seseorang mencuri payungku."},{"jp":"だれか助けてください。","romaji":"Dareka tasukete kudasai.","en":"Someone, please help.","id":"Seseorang, tolong bantu."},{"jp":"だれかのせいで、電気がきれました。","romaji":"Dareka no sei de, denki ga kiremashita.","en":"Because of someone, the electricity went out.","id":"Gara-gara ada orang, listrik padam."}]},{"pattern":"だれでも～","meaning":"Used to express 'anyone' or 'everyone'; 'no matter who'.","meaningId":"Digunakan untuk menyatakan 'siapa pun' atau 'semua orang'; 'tidak peduli siapa'.","formation":"だれでも + Verb/Adjective/Noun","formationId":"だれでも + Kata Kerja/Kata Sifat/Kata Benda","examples":[{"jp":"だれでもこのゲームができます。","romaji":"Dare demo kono geemu ga dekimasu.","en":"Anyone can play this game.","id":"Siapapun bisa memainkan permainan ini."},{"jp":"だれでも疲れることがあります。","romaji":"Dare demo tsukareru koto ga arimasu.","en":"Everyone gets tired sometimes.","id":"Setiap orang terkadang merasa lelah."},{"jp":"だれでも無料でこのイベントに参加できます。","romaji":"Dare demo muryou de kono ibento ni sanka dekimasu.","en":"Anyone can participate in this event for free.","id":"Siapa pun dapat berpartisipasi dalam acara ini secara gratis."},{"jp":"だれでもこの町の観光スポットを楽しむことができます。","romaji":"Dare demo kono machi no kankou supotto wo tanoshimu koto ga dekimasu.","en":"No matter who you are, you can enjoy the sightseeing spots in this town.","id":"Siapa pun Anda, Anda dapat menikmati tempat-tempat wisata di kota ini."}]},{"pattern":"だれも～ないです","meaning":"Express 'nobody' or 'no one' in a negative sentence.","meaningId":"Ekspresikan 'tidak seorang pun' atau 'tidak seorang pun' dalam kalimat negatif.","formation":"だれも + Verb-negative form (ないです), だれも + い-Adjective-negative form (ないです), だれも + な-Adjective-negative form (じゃないです)","formationId":"だれも + Bentuk kata kerja-negatif (ないです), だれも + い-Bentuk kata sifat-negatif (ないです), だれも + な-Bentuk kata sifat-negatif (じゃないです)","examples":[{"jp":"だれも知らないです。","romaji":"Daremo shiranai desu.","en":"Nobody knows.","id":"Tidak ada yang tahu."},{"jp":"だれも来ないです。","romaji":"Daremo konai desu.","en":"Nobody is coming.","id":"Tidak ada yang datang."},{"jp":"彼女はだれも好きじゃないです。","romaji":"Kanojo wa daremo suki ja nai desu.","en":"She doesn't like anyone.","id":"Dia tidak menyukai siapa pun."},{"jp":"ここにはだれもいないです。","romaji":"Koko ni wa daremo inai desu.","en":"There is nobody here.","id":"Tidak ada seorang pun di sini."}]},{"pattern":"だれも～ません","meaning":"Express 'nobody' or 'no one' in negative sentences.","meaningId":"Nyatakan 'tidak seorang pun' atau 'tidak seorang pun' dalam kalimat negatif.","formation":"だれも + Verb-negative (ません)","formationId":"だれも + Kata Kerja-negatif (ません)","examples":[{"jp":"だれも秘密を知りません。","romaji":"Daremo himitsu wo shirimasen.","en":"No one knows the secret.","id":"Tidak ada yang tahu rahasianya."},{"jp":"だれもその質問に答えませんでした。","romaji":"Daremo sono shitsumon ni kotaemasen deshita.","en":"Nobody answered that question.","id":"Tidak ada yang menjawab pertanyaan itu."},{"jp":"だれも彼を助けてあげません。","romaji":"Daremo kare wo tasukete agemasen.","en":"Nobody will help him.","id":"Tidak ada yang akan membantunya."},{"jp":"だれもその映画を見たがりません。","romaji":"Daremo sono eiga wo mitagarimasen.","en":"No one wants to watch that movie.","id":"Tidak ada yang mau menonton film itu."}]},{"pattern":"～どう しますか。 (～dou shimasu ka.)","meaning":"Asking for someone's opinion or decision; 'what will you do?', 'how will you handle it?'.","meaningId":"Meminta pendapat atau keputusan seseorang; 'apa yang akan kamu lakukan?', 'bagaimana kamu menanganinya?'.","formation":"Situation + どうしますか","formationId":"Situasi + どうしますか","examples":[{"jp":"雨が降っているので、どうしますか？","romaji":"Ame ga futte iru node, dou shimasu ka?","en":"It's raining, so what will you do?","id":"Hujan turun, jadi apa yang akan kamu lakukan?"},{"jp":"この問題について、どうしますか？","romaji":"Kono mondai ni tsuite, dou shimasu ka?","en":"What are you going to do about this issue?","id":"Apa yang akan Anda lakukan mengenai masalah ini?"},{"jp":"彼が来なかったら、どうしますか？","romaji":"Kare ga konakattara, dou shimasu ka?","en":"If he doesn't come, what will you do?","id":"Jika dia tidak datang, apa yang akan kamu lakukan?"},{"jp":"進路を決める時、どうしますか？","romaji":"Shinro wo kimeru toki, dou shimasu ka?","en":"What will you do when choosing your career path?","id":"Apa yang akan Anda lakukan ketika memilih jalur karier Anda?"}]},{"pattern":"～どうですか。 (〜dou desu ka.)","meaning":"Asking for opinions or suggestions; 'how about', 'what do you think of'.","meaningId":"Meminta pendapat atau saran; 'bagaimana dengan', 'apa pendapatmu'.","formation":"Noun + は/が + どうですか / Verb-casual + の + どうですか / い-Adjective + どうですか / な-Adjective + な + どうですか","formationId":"Kata Benda + は/が + どうですか / Kata Kerja-kasual + の + どうですか / い-Kata Sifat + どうですか / な-Kata Sifat + な + どうですか","examples":[{"jp":"この映画はどうですか？","romaji":"Kono eiga wa dou desu ka?","en":"How about this movie? / What do you think of this movie?","id":"Bagaimana dengan film ini? / Apa pendapatmu tentang film ini?"},{"jp":"晩ご飯に寿司を食べるのはどうですか？","romaji":"Bangohan ni sushi wo taberu no wa dou desu ka?","en":"How about eating sushi for dinner?","id":"Bagaimana kalau makan sushi untuk makan malam?"},{"jp":"この部屋は広いと思いますが、どうですか？","romaji":"Kono heya wa hiroi to omoimasu ga, dou desu ka?","en":"I think this room is spacious, what do you think?","id":"Menurut saya ruangan ini luas, bagaimana menurut Anda?"},{"jp":"新しい会社の要件が厳しいですね。鈴木さん、転職するならどうですか？","romaji":"Atarashii kaisha no youken ga kibishii desu ne. Suzuki-san, tenshoku suru nara dou desu ka?","en":"The new company's requirements are strict, aren't they? Suzuki-san, how about changing jobs if that's the case?","id":"Persyaratan perusahaan baru sangat ketat, bukan? Suzuki-san, bagaimana kalau berganti pekerjaan jika itu masalahnya?"}]},{"pattern":"どうやって～","meaning":"Ask 'how' something is done or how to do something.","meaningId":"Tanyakan 'bagaimana' sesuatu dilakukan atau bagaimana melakukan sesuatu.","formation":"どうやって + Verb-casual","formationId":"どうやって + Kata Kerja-santai","examples":[{"jp":"どうやってお寿司を作りますか？","romaji":"Douyatte o-sushi wo tsukurimasu ka?","en":"How do you make sushi?","id":"Bagaimana cara membuat sushi?"},{"jp":"どうやって日本語を勉強しましたか？","romaji":"Douyatte nihongo wo benkyou shimashita ka?","en":"How did you study Japanese?","id":"Bagaimana Anda belajar bahasa Jepang?"},{"jp":"どうやってこの問題を解決しますか？","romaji":"Douyatte kono mondai wo kaiketsu shimasu ka?","en":"How do you solve this problem?","id":"Bagaimana Anda mengatasi masalah ini?"},{"jp":"どうやって駅に行きますか？","romaji":"Douyatte eki ni ikimasu ka?","en":"How do you go to the station?","id":"Bagaimana caranya pergi ke stasiun?"}]},{"pattern":"～どう 言いますか。 (〜dou iimasu ka.)","meaning":"Asking for the way to say something; 'how do you say'.","meaningId":"Menanyakan cara untuk mengatakan sesuatu; 'bagaimana kamu mengatakannya'.","formation":"Word/Phrase + は [language]でどう言いますか / Word/Phrase + をどう言いますか","formationId":"Kata/Frase + は [bahasa]でどう言いますか / Kata/Frase + をどう言いますか","examples":[{"jp":"「ありがとう」は英語でどう言いますか。","romaji":"「Arigatou」wa eigo de dou iimasu ka.","en":"How do you say 'thank you' in English?","id":"Bagaimana cara mengucapkan 'terima kasih' dalam bahasa Inggris?"},{"jp":"この言葉を日本語でどう言いますか。","romaji":"Kono kotoba wo nihongo de dou iimasu ka.","en":"How do you say this word in Japanese?","id":"Bagaimana cara mengucapkan kata ini dalam bahasa Jepang?"},{"jp":"「すみません」はフランス語でどう言いますか。","romaji":"「Sumimasen」wa furansugo de dou iimasu ka.","en":"How do you say 'excuse me' in French?","id":"Bagaimana cara mengucapkan 'permisi' dalam bahasa Prancis?"},{"jp":"その表現をスペイン語でどう言いますか。","romaji":"Sono hyougen wo supeingo de dou iimasu ka.","en":"How do you say that expression in Spanish?","id":"Bagaimana Anda mengucapkan ungkapan itu dalam bahasa Spanyol?"}]},{"pattern":"～とき (〜toki)","meaning":"Expresses the time when something happens, 'when', 'at the time'.","meaningId":"Menyatakan waktu ketika sesuatu terjadi, 'kapan', 'pada saat itu'.","formation":"Verb-casual + とき / い-Adjective + とき / な-Adjective + なとき / Noun + のとき","formationId":"Kata Kerja-kasual + とき / い-Kata Sifat + とき / な-Kata Sifat + なとき / Kata Benda + のとき","examples":[{"jp":"公園で遊ぶとき、帽子をかぶりましょう。","romaji":"Kouen de asobu toki, boushi wo kaburimashou.","en":"When playing in the park, let's wear a hat.","id":"Kalau main di taman, ayo pakai topi."},{"jp":"このりんごが赤いとき、食べごろです。","romaji":"Kono ringo ga akai toki, tabegoro desu.","en":"This apple is ready to eat when it is red.","id":"Apel ini siap disantap jika warnanya merah."},{"jp":"私が勉強するとき、家族は静かにしてくれます。","romaji":"Watashi ga benkyou suru toki, kazoku wa shizuka ni shite kuremasu.","en":"When I am studying, my family keeps quiet for me.","id":"Ketika saya sedang belajar, keluarga saya tetap diam untuk saya."},{"jp":"子供のとき、よくおばあちゃんの家に遊びに行きました。","romaji":"Kodomo no toki, yoku obaachan no ie ni asobi ni ikimashita.","en":"When I was a child, I often went to play at my grandmother's house.","id":"Ketika saya masih kecil, saya sering pergi bermain ke rumah nenek saya."}]},{"pattern":"ときどき～","meaning":"Used to indicate the frequency of an event; 'sometimes', 'occasionally', 'now and then'.","meaningId":"Digunakan untuk menunjukkan frekuensi suatu peristiwa; 'kadang-kadang', 'kadang-kadang', 'sekali-sekali'.","formation":"ときどき + Verb/Adjective/Noun","formationId":"ときどき + Kata Kerja/Kata Sifat/Kata Benda","examples":[{"jp":"彼はときどきケーキを作ります。","romaji":"Kare wa tokidoki keeki o tsukurimasu.","en":"He sometimes makes cakes.","id":"Dia terkadang membuat kue."},{"jp":"ときどき雨が降るので、傘を持って行ったほうがいいです。","romaji":"Tokidoki ame ga furu node, kasa o motte itta hou ga ii desu.","en":"It occasionally rains, so it's better to bring an umbrella.","id":"Kadang-kadang hujan, jadi lebih baik membawa payung."},{"jp":"私はときどきこの店で買い物をします。","romaji":"Watashi wa tokidoki kono mise de kaimono o shimasu.","en":"I shop at this store now and then.","id":"Saya berbelanja di toko ini sesekali."},{"jp":"彼女はときどき遅刻します。","romaji":"Kanojo wa tokidoki chikoku shimasu.","en":"She is sometimes late.","id":"Dia terkadang terlambat."}]},{"pattern":"どこ～","meaning":"Express 'where', used with question words for asking about locations.","meaningId":"Ekspresikan 'di mana', digunakan dengan kata tanya untuk menanyakan tentang lokasi.","formation":"どこ + question particle","formationId":"どこ + partikel pertanyaan","examples":[{"jp":"駅はどこですか？","romaji":"Eki wa doko desu ka?","en":"Where is the station?","id":"Dimana stasiunnya?"},{"jp":"どこで映画を見ましたか？","romaji":"Doko de eiga wo mimashita ka?","en":"Where did you watch the movie?","id":"Di mana Anda menonton filmnya?"},{"jp":"どこに住んでいますか？","romaji":"Doko ni sunde imasu ka?","en":"Where do you live?","id":"Kamu tinggal di mana?"},{"jp":"どこへ行きたいですか？","romaji":"Doko e ikitai desu ka?","en":"Where do you want to go?","id":"Kemana kamu ingin pergi?"}]},{"pattern":"どこか～","meaning":"Expresses 'somewhere', used when the specific location is unknown or uncertain.","meaningId":"Menyatakan 'di suatu tempat', digunakan ketika lokasi tertentu tidak diketahui atau tidak pasti.","formation":"どこか + (Particle, if needed) + Verb/Noun/Adjective","formationId":"どこか + (Partikel, jika diperlukan) + Kata Kerja/Kata Benda/Kata Sifat","examples":[{"jp":"どこかで財布をなくしました。","romaji":"Dokoka de saifu wo nakushimashita.","en":"I lost my wallet somewhere.","id":"Saya kehilangan dompet saya di suatu tempat."},{"jp":"今日はどこかに行きたいです。","romaji":"Kyou wa dokoka ni ikitai desu.","en":"I want to go somewhere today.","id":"Saya ingin pergi ke suatu tempat hari ini."},{"jp":"どこか安いレストランがありますか？","romaji":"Dokoka yasui resutoran ga arimasu ka?","en":"Is there a cheap restaurant somewhere?","id":"Apakah ada restoran murah di suatu tempat?"},{"jp":"どこか静かな場所で勉強したい。","romaji":"Dokoka shizuka na basho de benkyou shitai.","en":"I want to study in a quiet place somewhere.","id":"Saya ingin belajar di tempat yang tenang di suatu tempat."}]},{"pattern":"どこでも～","meaning":"Express 'anywhere' or 'everywhere' in Japanese.","meaningId":"Ekspresikan 'di mana saja' atau 'di mana saja' dalam bahasa Jepang.","formation":"Simply use the word どこでも in the sentence as an adverb to indicate 'anywhere' or 'everywhere'.","formationId":"Cukup gunakan kata どこでも dalam kalimat sebagai kata keterangan untuk menunjukkan 'di mana saja' atau 'di mana saja'.","examples":[{"jp":"どこでも好きな場所で勉強できます。","romaji":"Dokodemo sukina basho de benkyou dekimasu.","en":"You can study anywhere you like.","id":"Anda dapat belajar di mana pun Anda suka."},{"jp":"このノートパソコンは便利なので、どこでもインターネットが使えます。","romaji":"Kono nootopasokon wa benri nano de, dokodemo intaanetto ga tsukaemasu.","en":"This laptop is convenient, so you can use the internet anywhere.","id":"Laptop ini nyaman, sehingga Anda dapat menggunakan internet di mana saja."},{"jp":"彼はどこでも寝ることができます。","romaji":"Kare wa dokodemo neru koto ga dekimasu.","en":"He can sleep anywhere.","id":"Dia bisa tidur dimana saja."},{"jp":"彼女はどこでも歌うのが大好きです。","romaji":"Kanojo wa dokodemo utau no ga daisuki desu.","en":"She loves singing anywhere.","id":"Dia suka bernyanyi di mana saja."}]},{"pattern":"どこにも + Verb + ないです (doko ni mo + Verb + nai desu)","meaning":"Express that an action cannot be performed anywhere or something cannot be found anywhere.","meaningId":"Nyatakan bahwa suatu tindakan tidak dapat dilakukan di mana pun atau sesuatu tidak dapat ditemukan di mana pun.","formation":"どこにも + Verb in ない-form + です","formationId":"どこにも + Kata Kerja dalam bentuk ない + です","examples":[{"jp":"どこにも傘が売ってないです。","romaji":"Doko ni mo kasa ga uttenai desu.","en":"Umbrellas are not sold anywhere.","id":"Payung tidak dijual dimanapun."},{"jp":"彼はどこにも見つけられないです。","romaji":"Kare wa doko ni mo mitsukerarenai desu.","en":"He cannot be found anywhere.","id":"Dia tidak dapat ditemukan di mana pun."},{"jp":"どこにも勉強できる場所がないです。","romaji":"Doko ni mo benkyou dekiru basho ga nai desu.","en":"There is no place to study anywhere.","id":"Tidak ada tempat untuk belajar di mana pun."},{"jp":"どこにも美味しいビーガン料理がないです。","romaji":"Doko ni mo oishii bi-gan ryouri ga nai desu.","en":"There are no delicious vegan dishes anywhere.","id":"Tidak ada hidangan vegan yang lezat di mana pun."}]},{"pattern":"どこにも + Verb + ません (doko ni mo + Verb + masen)","meaning":"Express 'not anywhere' or 'nowhere' with a negative verb.","meaningId":"Ekspresikan 'tidak di mana pun' atau 'tidak di mana pun' dengan kata kerja negatif.","formation":"どこにも + Verb-negative","formationId":"どこにも + Kata kerja-negatif","examples":[{"jp":"どこにもあの猫がいません。","romaji":"Doko ni mo ano neko ga imasen.","en":"The cat is not anywhere.","id":"Kucing itu tidak ada dimana-mana."},{"jp":"どこにもお金を置いていません。","romaji":"Doko ni mo okane wo oiteimasen.","en":"I didn't put the money anywhere.","id":"Saya tidak menaruh uang itu di mana pun."},{"jp":"この町にはどこにも美味しいラーメン屋がありません。","romaji":"Kono machi ni wa doko ni mo oishii raamenya ga arimasen.","en":"There are no delicious ramen shops anywhere in this town.","id":"Tidak ada toko ramen lezat di kota ini."},{"jp":"どこにも彼女の名前が書いていません。","romaji":"Doko ni mo kanojo no namae ga kaiteimasen.","en":"Her name is not written anywhere.","id":"Namanya tidak tertulis dimanapun."}]},{"pattern":"どこへも Verb ないです (doko e mo + Verb + nai desu)","meaning":"Express that an action doesn't take place anywhere; 'nowhere', 'not anywhere'.","meaningId":"Nyatakan bahwa suatu tindakan tidak terjadi di mana pun; 'tidak di mana pun', 'tidak di mana pun'.","formation":"どこへも + Verb in negative form (ないです)","formationId":"どこへも + Kata Kerja dalam bentuk negatif (ないです)","examples":[{"jp":"今週末どこへも行かないです。","romaji":"Konshuumatsu doko e mo ikanai desu.","en":"I'm not going anywhere this weekend.","id":"Aku tidak akan kemana-mana akhir pekan ini."},{"jp":"彼女はどこへも買い物に行きませんでした。","romaji":"Kanojo wa doko e mo kaimono ni ikimasen deshita.","en":"She didn't go shopping anywhere.","id":"Dia tidak pergi berbelanja kemana pun."},{"jp":"スーパーはどこへも売らないです。","romaji":"Suupaa wa doko e mo uranai desu.","en":"It's not sold at any supermarket.","id":"Itu tidak dijual di supermarket mana pun."},{"jp":"私はどこへも行く予定がないです。","romaji":"Watashi wa doko e mo iku yotei ga nai desu.","en":"I have no plans to go anywhere.","id":"Saya tidak punya rencana untuk pergi ke mana pun."}]},{"pattern":"どこへも Verb ません (doko e mo + Verb + masen)","meaning":"Nowhere; Not to any place","meaningId":"Tidak ada tempat; Tidak ke sembarang tempat","formation":"どこへも + Verb-negative","formationId":"どこへも + Kata Kerja-negatif","examples":[{"jp":"今日はどこへも行きません。","romaji":"Kyou wa doko e mo ikimasen.","en":"I won't go anywhere today.","id":"Saya tidak akan pergi ke mana pun hari ini."},{"jp":"彼はどこへも走りませんでした。","romaji":"Kare wa doko e mo hashirimasen deshita.","en":"He didn't run anywhere.","id":"Dia tidak lari kemana-mana."},{"jp":"どこへも買い物に行きませんでした。","romaji":"Doko e mo kaimono ni ikimasen deshita.","en":"I didn't go shopping anywhere.","id":"Saya tidak pergi berbelanja ke mana pun."},{"jp":"彼女はどこへも連れて行かせません。","romaji":"Kanojo wa doko e mo tsurete ikasemasen.","en":"She won't take me anywhere.","id":"Dia tidak akan membawaku kemana pun."}]},{"pattern":"どこも Verb ないです (dokomo + Verb + naidesu)","meaning":"Express that something cannot be found anywhere or in any place; 'nowhere', 'in no place'.","meaningId":"Menyatakan bahwa sesuatu tidak dapat ditemukan di mana pun atau di mana pun; 'tidak ada tempat', 'tidak ada tempat'.","formation":"どこも + Verb-negative","formationId":"どこも + Kata kerja-negatif","examples":[{"jp":"どこもうちわがないです。","romaji":"Doko mo uchiwa ga nai desu.","en":"I can't find fans anywhere.","id":"Saya tidak dapat menemukan penggemar di mana pun."},{"jp":"この町ではどこも美味しいラーメンがないです。","romaji":"Kono machi de wa doko mo oishii raamen ga nai desu.","en":"There are no delicious ramen shops anywhere in this town.","id":"Tidak ada toko ramen lezat di kota ini."},{"jp":"どこも駐車場がないです。","romaji":"Doko mo chuushajou ga nai desu.","en":"There is no parking anywhere.","id":"Tidak ada tempat parkir di mana pun."},{"jp":"どこも席がないです。","romaji":"Doko mo seki ga nai desu.","en":"There are no seats available anywhere.","id":"Tidak ada kursi yang tersedia di mana pun."}]},{"pattern":"どこも Verb ません (dokomo + Verb + masen)","meaning":"Express that 'nowhere' meets the verb action; 'nowhere does/can'.","meaningId":"Nyatakan bahwa 'tidak ada tempat' bertemu dengan kata kerja tindakan; 'tidak ada tempat/bisa'.","formation":"どこも + Verb-ます form + ません","formationId":"どこも + Bentuk kata kerja-ます + ません","examples":[{"jp":"どこも静かじゃありません。","romaji":"Doko mo shizuka ja arimasen.","en":"Nowhere is quiet.","id":"Tidak ada tempat yang sepi."},{"jp":"どこもその本を売っていません。","romaji":"Doko mo sono hon wo utte imasen.","en":"Nowhere sells that book.","id":"Tidak ada tempat yang menjual buku itu."},{"jp":"この地域では、どこもインターネットに接続できません。","romaji":"Kono chiiki de wa, doko mo intaanetto ni setsuzoku dekimasen.","en":"In this area, nowhere can connect to the internet.","id":"Di area ini, tidak ada tempat yang bisa terhubung ke internet."},{"jp":"どこも彼を知りません。","romaji":"Doko mo kare wo shirimasen.","en":"No place knows him.","id":"Tidak ada tempat yang mengenalnya."}]},{"pattern":"どちら～","meaning":"Used to ask about two choices or options.","meaningId":"Digunakan untuk menanyakan tentang dua pilihan atau pilihan.","formation":"どちら + が/を + verb, どちら + が/を + adjective, どちら + が/を + noun","formationId":"どちら + が/を + kata kerja, どちら + が/を + kata sifat, どちら + が/を + kata benda","examples":[{"jp":"この二つのリンゴ、どちらが美味しいですか？","romaji":"Kono futatsu no ringo, dochira ga oishii desu ka?","en":"Which of these two apples is delicious?","id":"Manakah dari dua apel berikut yang enak?"},{"jp":"どちらのドレスを着たいですか？","romaji":"Dochira no doresu wo kitai desu ka?","en":"Which dress would you like to wear?","id":"Gaun mana yang ingin Anda kenakan?"},{"jp":"この二つの町、どちらに行きたいですか？","romaji":"Kono futatsu no machi, dochira ni ikitai desu ka?","en":"Which of these two towns do you want to go to?","id":"Di antara dua kota berikut, manakah yang ingin Anda kunjungi?"},{"jp":"どちらの映画が面白いと思いますか？","romaji":"Dochira no eiga ga omoshiroi to omoimasu ka?","en":"Which movie do you think is interesting?","id":"Film mana yang menurutmu menarik?"}]},{"pattern":"どなた～","meaning":"A polite way to ask 'who', used for asking about someone's identity or when seeking information about an unknown person.","meaningId":"Cara sopan menanyakan 'siapa', digunakan untuk menanyakan identitas seseorang atau saat mencari informasi tentang orang yang tidak dikenal.","formation":"どなた","formationId":"どなた","examples":[{"jp":"すみません、どなたが山田さんですか？","romaji":"Sumimasen, donata ga Yamada-san desu ka?","en":"Excuse me, who is Mr. Yamada?","id":"Permisi, siapa Tuan Yamada?"},{"jp":"どなたも知っている有名な俳優です。","romaji":"Donata mo shitte iru yuumei na haiyuu desu.","en":"He is a famous actor whom everyone knows.","id":"Dia adalah aktor terkenal yang semua orang tahu."},{"jp":"明日のパーティーにはどなたが来ますか？","romaji":"Ashita no paatii ni wa donata ga kimasu ka?","en":"Who is coming to the party tomorrow?","id":"Siapa yang datang ke pesta besok?"},{"jp":"どなたか手伝っていただけますか？","romaji":"Donata ka tetsudatte itadakemasu ka?","en":"Could someone please help me?","id":"Bisakah seseorang tolong bantu saya?"}]},{"pattern":"どの Noun","meaning":"Expresses 'which'; used to ask about specific items within a group.","meaningId":"Mengekspresikan 'yang mana'; digunakan untuk menanyakan tentang item tertentu dalam suatu kelompok.","formation":"どの + Noun","formationId":"どの + Kata Benda","examples":[{"jp":"どの本が一番面白いですか。","romaji":"Dono hon ga ichiban omoshiroi desu ka?","en":"Which book is the most interesting?","id":"Buku manakah yang paling menarik?"},{"jp":"どの服を着たいですか。","romaji":"Dono fuku wo kitai desu ka?","en":"Which clothes do you want to wear?","id":"Baju apa yang ingin kamu pakai?"},{"jp":"どの色が好きですか。","romaji":"Dono iro ga suki desu ka?","en":"Which color do you like?","id":"Warna apa yang kamu suka?"},{"jp":"どのレストランに行きたいですか。","romaji":"Dono resutoran ni ikitai desu ka?","en":"Which restaurant do you want to go to?","id":"Restoran mana yang ingin Anda kunjungi?"}]},{"pattern":"どれでも～","meaning":"Indicates 'any' or 'whichever' when referring to multiple items.","meaningId":"Menunjukkan 'apa saja' atau 'yang mana saja' ketika mengacu pada beberapa item.","formation":"どれ + でも","formationId":"どれ + でも","examples":[{"jp":"どれでもいいですか？","romaji":"Dore demo ii desu ka?","en":"Is any choice okay?","id":"Apakah ada pilihan yang oke?"},{"jp":"どれでも選んでください。","romaji":"Dore demo erande kudasai.","en":"Please choose whichever you like.","id":"Silakan pilih mana yang Anda suka."},{"jp":"どれでもおいしいです。","romaji":"Dore demo oishii desu.","en":"All of them are delicious.","id":"Semuanya enak."},{"jp":"この中でどれでも好きなものを持って行ってください。","romaji":"Kono naka de dore demo suki na mono wo motte itte kudasai.","en":"Please take whichever you like from these.","id":"Silakan ambil mana saja yang Anda suka dari ini."}]},{"pattern":"どんな Noun","meaning":"Used to ask or describe 'what kind' or 'what type' of something.","meaningId":"Digunakan untuk menanyakan atau mendeskripsikan 'jenis apa' atau 'tipe apa' dari sesuatu.","formation":"どんな + Noun","formationId":"どんな + Kata Benda","examples":[{"jp":"どんな音楽が好きですか？","romaji":"Donna ongaku ga suki desu ka?","en":"What kind of music do you like?","id":"Jenis musik apa yang kamu suka?"},{"jp":"彼女はどんな映画が好きだと思う？","romaji":"Kanojo wa donna eiga ga suki da to omou?","en":"What kind of movies do you think she likes?","id":"Menurutmu, jenis film apa yang dia sukai?"},{"jp":"どんな本が一番面白いですか？","romaji":"Donna hon ga ichiban omoshiroi desu ka?","en":"What kind of books are the most interesting?","id":"Jenis buku apa yang paling menarik?"},{"jp":"どんな料理が得意ですか？","romaji":"Donna ryouri ga tokui desu ka?","en":"What kind of dishes are you good at making?","id":"Jenis masakan apa yang kamu kuasai?"}]},{"pattern":"なに～","meaning":"Asking about 'what' or 'which' in Japanese","meaningId":"Menanyakan tentang 'apa' atau 'yang mana' dalam bahasa Jepang","formation":"Verb + なに, い-Adjective + なに, な-Adjective + なに, Noun + なに","formationId":"Kata Kerja + なに, い-Kata Sifat + なに, な-Kata Sifat + なに, Kata Benda + なに","examples":[{"jp":"これはなにですか。","romaji":"Kore wa nani desu ka?","en":"What is this?","id":"Apa ini?"},{"jp":"あの人はなにをしているのですか？","romaji":"Ano hito wa nani wo shite iru no desu ka?","en":"What is that person doing?","id":"Apa yang sedang dilakukan orang itu?"},{"jp":"なにが好きですか？","romaji":"Nani ga suki desu ka?","en":"What do you like?","id":"Apa yang kamu suka?"},{"jp":"今日の天気はなにですか？","romaji":"Kyou no tenki wa nani desu ka?","en":"What is today's weather?","id":"Bagaimana cuaca hari ini?"}]},{"pattern":"なにか～","meaning":"Indicates 'something' or 'some kind of'.","meaningId":"Menunjukkan 'sesuatu' atau 'semacam'.","formation":"なにか + Noun","formationId":"なにか + Kata Benda","examples":[{"jp":"なにか飲み物を持ってきてください。","romaji":"Nanika nomimono wo motte kite kudasai.","en":"Please bring some kind of drink.","id":"Tolong bawakan minuman."},{"jp":"なにか質問があれば、遠慮なく聞いてください。","romaji":"Nanika shitsumon ga areba, enryo naku kiite kudasai.","en":"If you have any questions, please feel free to ask.","id":"Jika Anda memiliki pertanyaan, jangan ragu untuk bertanya."},{"jp":"彼女はなにかプレゼントを持っている。","romaji":"Kanojo wa nanika purezento wo motte iru.","en":"She has some kind of present.","id":"Dia punya semacam hadiah."},{"jp":"なにか助けが必要なら、言ってください。","romaji":"Nanika tasuke ga hitsuyou nara, itte kudasai.","en":"If you need any help, please let me know.","id":"Jika Anda memerlukan bantuan, silakan beri tahu saya."}]},{"pattern":"なにも～ないです","meaning":"Used to express 'not any' or 'nothing' in a negative sentence.","meaningId":"Digunakan untuk menyatakan 'tidak ada' atau 'tidak ada' dalam kalimat negatif.","formation":"なにも + Verb-negative","formationId":"なにも + Kata Kerja-negatif","examples":[{"jp":"彼はなにも言わなかったです。","romaji":"Kare wa nani mo iwanakatta desu.","en":"He didn't say anything.","id":"Dia tidak mengatakan apa pun."},{"jp":"私はなにも食べないです。","romaji":"Watashi wa nani mo tabenai desu.","en":"I don't eat anything.","id":"Saya tidak makan apa pun."},{"jp":"彼女はなにも持っていないです。","romaji":"Kanojo wa nani mo motte inai desu.","en":"She doesn't have anything.","id":"Dia tidak punya apa-apa."},{"jp":"この箱にはなにも入っていないです。","romaji":"Kono hako ni wa nani mo haitte inai desu.","en":"There is nothing in this box.","id":"Tidak ada apa pun di dalam kotak ini."}]},{"pattern":"なにも～ません","meaning":"Used to express 'not anything', 'nothing'.","meaningId":"Digunakan untuk menyatakan 'tidak apa-apa', 'tidak ada apa-apa'.","formation":"なにも + Verb-ます form + ません","formationId":"なにも + Bentuk kata kerja-ます + ません","examples":[{"jp":"昨日はなにも食べませんでした。","romaji":"Kinou wa nanimo tabemasen deshita.","en":"I didn't eat anything yesterday.","id":"Saya tidak makan apa pun kemarin."},{"jp":"彼はなにも話しません。","romaji":"Kare wa nanimo hanashimasen.","en":"He doesn't say anything.","id":"Dia tidak mengatakan apa-apa."},{"jp":"この部屋ではなにも見えません。","romaji":"Kono heya de wa nanimo miemasen.","en":"I cannot see anything in this room.","id":"Saya tidak dapat melihat apa pun di ruangan ini."},{"jp":"彼女はなにも買いませんでした。","romaji":"Kanojo wa nanimo kaimasen deshita.","en":"She didn't buy anything.","id":"Dia tidak membeli apa pun."}]},{"pattern":"なん～","meaning":"Used to form interrogative questions and emphasize the question word for 'what', 'how'.","meaningId":"Digunakan untuk membentuk pertanyaan interogatif dan menekankan kata tanya untuk 'apa', 'bagaimana'.","formation":"なん + Counter / なん + Verb / なん + Adjective","formationId":"なん + Penghitung / なん + Kata Kerja / なん + Kata Sifat","examples":[{"jp":"あなたはなん歳ですか？","romaji":"Anata wa nan-sai desu ka?","en":"How old are you?","id":"Berapa usiamu?"},{"jp":"これはなんですか？","romaji":"Kore wa nan desu ka?","en":"What is this?","id":"Apa ini?"},{"jp":"彼はなんで来ましたか？","romaji":"Kare wa nan de kimashita ka?","en":"Why did he come?","id":"Kenapa dia datang?"},{"jp":"あのレストランはなんと言う名前ですか？","romaji":"Ano resutoran wa nan to iu namae desu ka?","en":"What is the name of that restaurant?","id":"Apa nama restoran itu?"}]},{"pattern":"なんで～","meaning":"Asking the reason or cause; 'why', 'how come'.","meaningId":"Menanyakan alasan atau penyebabnya; 'kenapa', 'kenapa'.","formation":"なんで + [phrase or sentence]","formationId":"なんで + [frasa atau kalimat]","examples":[{"jp":"なんで遅れたの？","romaji":"Nande okureta no?","en":"Why were you late?","id":"Kenapa kamu terlambat?"},{"jp":"なんでこの部屋はこんなに汚いの？","romaji":"Nande kono heya wa konna ni kitanai no?","en":"Why is this room so dirty?","id":"Mengapa ruangan ini sangat kotor?"},{"jp":"なんで彼女は怒っているの？","romaji":"Nande kanojo wa okotte iru no?","en":"Why is she angry?","id":"Kenapa dia marah?"},{"jp":"なんで今日は休みなの？","romaji":"Nande kyou wa yasumi na no?","en":"Why is today a holiday?","id":"Mengapa hari ini adalah hari libur?"}]},{"pattern":"なんでも～","meaning":"Means 'any', 'anything', 'anyone'.","meaningId":"Berarti 'siapa saja', 'apa saja', 'siapa saja'.","formation":"なんでも + Verb / なんでも + Adjective / なんでも + Noun","formationId":"なんでも + Kata Kerja / なんでも + Kata Sifat / なんでも + Kata Benda","examples":[{"jp":"なんでも食べられるから、何を頼んでも大丈夫です。","romaji":"Nandemo taberareru kara, nani wo tanondemo daijoubu desu.","en":"I can eat anything, so it's okay to order whatever you want.","id":"Saya bisa makan apa saja, jadi tidak apa-apa memesan apa pun yang Anda mau."},{"jp":"なんでもよければ、この本をおすすめします。","romaji":"Nandemo yokereba, kono hon wo osusume shimasu.","en":"If you're okay with anything, I recommend this book.","id":"Jika Anda setuju dengan apa pun, saya merekomendasikan buku ini."},{"jp":"なんでもできるスタッフを探しています。","romaji":"Nandemo dekiru sutaffu wo sagashiteimasu.","en":"We are looking for a staff member who can do anything.","id":"Kami mencari anggota staf yang bisa melakukan apa saja."},{"jp":"この食堂では、なんでも美味しくて安い料理が出されます。","romaji":"Kono shokudou de wa, nandemo oishikute yasui ryouri ga dasaremasu.","en":"In this cafeteria, any dish served is delicious and inexpensive.","id":"Di kafetaria ini, hidangan apa pun yang disajikan enak dan murah."}]},{"pattern":"～なんと 言いますか。 (〜nan to iimasu ka.)","meaning":"Asking how something is called or referred to; 'how do you say'","meaningId":"Menanyakan bagaimana sesuatu disebut atau dirujuk; 'bagaimana kamu mengatakannya'","formation":"Noun + は/が + なんと言いますか","formationId":"Kata benda + は/が + なんと言いますか","examples":[{"jp":"この花はなんと言いますか。","romaji":"Kono hana wa nan to iimasu ka.","en":"How do you say this flower?","id":"Bagaimana kamu mengatakan bunga ini?"},{"jp":"この料理はなんと言いますか。","romaji":"Kono ryouri wa nan to iimasu ka.","en":"What do you call this dish?","id":"Apa nama hidangan ini?"},{"jp":"日本でこれはなんと言いますか。","romaji":"Nihon de kore wa nan to iimasu ka.","en":"How do you say this in Japanese?","id":"Bagaimana Anda mengatakan ini dalam bahasa Jepang?"},{"jp":"その映画の名前はなんと言いますか。","romaji":"Sono eiga no namae wa nan to iimasu ka.","en":"What is the name of that movie?","id":"Apa nama film itu?"}]},{"pattern":"～に あげます (〜 ni agemasu)","meaning":"Used to express giving something to someone; 'give', 'offer'.","meaningId":"Digunakan untuk menyatakan memberikan sesuatu kepada seseorang; 'memberi', 'menawarkan'.","formation":"Receiver + に + Object + を + あげます","formationId":"Penerima + に + Objek + を + あげます","examples":[{"jp":"私は友達に本をあげました。","romaji":"Watashi wa tomodachi ni hon wo agemashita.","en":"I gave a book to my friend.","id":"Saya memberikan sebuah buku kepada teman saya."},{"jp":"彼にプレゼントをあげましょう。","romaji":"Kare ni purezento wo agemashou.","en":"Let's give him a present.","id":"Ayo beri dia hadiah."},{"jp":"先生に花をあげます。","romaji":"Sensei ni hana wo agemasu.","en":"I will give flowers to the teacher.","id":"Saya akan memberikan bunga kepada guru."},{"jp":"お母さんにチョコレートをあげたいです。","romaji":"Okaasan ni chokoreeto wo agetai desu.","en":"I want to give chocolate to my mom.","id":"Aku ingin memberikan coklat pada ibuku."}]},{"pattern":"～に もらいます (〜ni moraimasu)","meaning":"To receive something or some action from someone; 'to get', 'to receive'.","meaningId":"Untuk menerima sesuatu atau tindakan dari seseorang; 'mendapatkan', 'menerima'.","formation":"Giver + に + Verb-te form + もらいます / Giver + に + Object + を + もらいます","formationId":"Pemberi + に + Bentuk kata kerja + もらいます / Pemberi + に + Objek + を + もらいます","examples":[{"jp":"友達にプレゼントをもらいました。","romaji":"Tomodachi ni purezento wo moraimashita.","en":"I received a gift from my friend.","id":"Saya menerima hadiah dari teman saya."},{"jp":"先生にアドバイスをもらいました。","romaji":"Sensei ni adobaisu wo moraimashita.","en":"I got advice from my teacher.","id":"Aku mendapat nasehat dari guruku."},{"jp":"おばあさんに手紙を書いてもらいました。","romaji":"Obaasan ni tegami wo kaite moraimashita.","en":"I had my grandmother write a letter for me.","id":"Saya meminta nenek saya menulis surat untuk saya."},{"jp":"弟に宿題を手伝ってもらいました。","romaji":"Otouto ni shukudai wo tetsudatte moraimashita.","en":"I got help from my younger brother with my homework.","id":"Saya mendapat bantuan dari adik laki-laki saya dengan pekerjaan rumah saya."}]},{"pattern":"～の (〜no)","meaning":"Express possession, apposition, or description using 'of' or ''s'.","meaningId":"Ekspresikan kepemilikan, aposisi, atau deskripsi menggunakan 'of' atau ''s'.","formation":"Noun1 + の + Noun2, (Adjective/Clause) + の (nominalized), etc.","formationId":"Kata Benda1 + の + Kata Benda2, (Kata Sifat/Klausul) + の (nominal), dsb.","examples":[{"jp":"これは私の鞄です。","romaji":"Kore wa watashi no kaban desu.","en":"This is my bag.","id":"Ini tasku."},{"jp":"彼女は赤いバッグを持っています。","romaji":"Kanojo wa akai baggu o motte imasu.","en":"She has a red bag.","id":"Dia memiliki tas merah."},{"jp":"彼はきれいな部屋があります。","romaji":"Kare wa kirei na heya ga arimasu.","en":"He has a clean room.","id":"Dia memiliki kamar yang bersih."},{"jp":"東京の天気は暑いです。","romaji":"Toukyou no tenki wa atsui desu.","en":"The weather in Tokyo is hot.","id":"Cuaca di Tokyo panas."}]},{"pattern":"～はたいへんです (〜wa taihen desu)","meaning":"Express that something is difficult or tough.","meaningId":"Ekspresikan bahwa ada sesuatu yang sulit atau sulit.","formation":"Noun + はたいへんです","formationId":"Kata benda + はたいへんです","examples":[{"jp":"漢字を覚えるのはたいへんです。","romaji":"Kanji o oboeru no wa taihen desu.","en":"It is difficult to remember kanji.","id":"Sulit untuk mengingat kanji."},{"jp":"この仕事はたいへんです。","romaji":"Kono shigoto wa taihen desu.","en":"This job is tough.","id":"Pekerjaan ini sulit."},{"jp":"日本の駅のことを理解するのはたいへんです。","romaji":"Nihon no eki no koto o rikai suru no wa taihen desu.","en":"Understanding Japanese train stations is difficult.","id":"Memahami stasiun kereta Jepang itu sulit."},{"jp":"彼女は病気の時、生活はたいへんです。","romaji":"Kanojo wa byouki no toki, seikatsu wa taihen desu.","en":"When she is sick, life is tough.","id":"Saat dia sakit, hidup menjadi sulit."}]},{"pattern":"ほとんど〜 (hotondo〜)","meaning":"Used to express 'almost', 'nearly', or 'most'.","meaningId":"Digunakan untuk menyatakan 'hampir', 'hampir', atau 'sebagian besar'.","formation":"ほとんど + Verb / ほとんど + Noun","formationId":"ほとんど + Kata Kerja / ほとんど + Kata Benda","examples":[{"jp":"彼女はほとんど英語を話せません。","romaji":"Kanojo wa hotondo eigo o hanasemasen.","en":"She can hardly speak English.","id":"Dia hampir tidak bisa berbahasa Inggris."},{"jp":"ほとんどの人がパーティーに出席しました。","romaji":"Hotondo no hito ga paatii ni shusseki shimashita.","en":"Most people attended the party.","id":"Kebanyakan orang menghadiri pesta itu."},{"jp":"私たちはほとんど勉強しないでテストに合格しました。","romaji":"Watashitachi wa hotondo benkyou shinaide tesuto ni goukaku shimashita.","en":"We passed the test with hardly any studying.","id":"Kami lulus ujian dengan hampir tidak belajar apa pun."},{"jp":"この本はほとんど読み終わりました。","romaji":"Kono hon wa hotondo yomiowarimashita.","en":"I have almost finished reading this book.","id":"Saya hampir selesai membaca buku ini."}]},{"pattern":"まあまあ～","meaning":"Expresses something as 'so-so', 'not bad', or 'average'.","meaningId":"Mengekspresikan sesuatu sebagai 'biasa saja', 'tidak buruk', atau 'rata-rata'.","formation":"Used as an adverb or short expression with no special grammar structure.","formationId":"Digunakan sebagai kata keterangan atau ekspresi singkat tanpa struktur tata bahasa khusus.","examples":[{"jp":"彼の料理の腕前はまあまあです。","romaji":"Kare no ryouri no udemae wa maa maa desu.","en":"His cooking skills are so-so.","id":"Keterampilan memasaknya biasa-biasa saja."},{"jp":"今日の天気はまあまあですね。","romaji":"Kyou no tenki wa maa maa desu ne.","en":"The weather today is not bad, huh?","id":"Cuaca hari ini tidak buruk ya?"},{"jp":"あの映画はまあまあ面白かったです。","romaji":"Ano eiga wa maa maa omoshirokatta desu.","en":"That movie was somewhat interesting.","id":"Film itu agak menarik."},{"jp":"彼女の歌はまあまあ上手だと思います。","romaji":"Kanojo no uta wa maa maa jouzu da to omoimasu.","en":"I think her singing is not bad.","id":"Menurutku nyanyiannya tidak buruk."}]},{"pattern":"まだ〜 (mada〜)","meaning":"Indicates something has not yet happened or is still happening; 'still', 'not yet'.","meaningId":"Menunjukkan sesuatu yang belum terjadi atau masih terjadi; 'masih belum'.","formation":"まだ + Verb (non-past / negative / te-form), まだ + い-adjective, まだ + な-adjective + じゃない/ではない, まだ + Noun + じゃない/ではない","formationId":"まだ + Kata Kerja (bukan masa lalu / negatif / bentuk-te), まだ + Kata sifat い, まだ + Kata sifat な + じゃない/ではない, まだ + Kata Benda +じゃない/ではない","examples":[{"jp":"昼ご飯はまだ食べていません。","romaji":"Hirugohan wa mada tabete imasen.","en":"I haven't eaten lunch yet.","id":"Saya belum makan siang."},{"jp":"山田さんはまだ来ていません。","romaji":"Yamada-san wa mada kite imasen.","en":"Yamada-san has not arrived yet.","id":"Yamada-san belum datang."},{"jp":"この部屋はまだ暑いです。","romaji":"Kono heya wa mada atsui desu.","en":"This room is still hot.","id":"Ruangan ini masih panas."},{"jp":"彼はまだ学生じゃないです。","romaji":"Kare wa mada gakusei ja nai desu.","en":"He is not a student yet.","id":"Dia belum menjadi pelajar."}]},{"pattern":"まだ〜ないです (mada 〜 nai desu)","meaning":"Expresses that something has not happened or been done yet.","meaningId":"Menyatakan bahwa sesuatu belum terjadi atau telah dilakukan.","formation":"まだ + Verb-negative + です","formationId":"まだ + Kata kerja-negatif + です","examples":[{"jp":"まだ宿題をしていないです。","romaji":"Mada shukudai o shite inai desu.","en":"I haven't done my homework yet.","id":"Saya belum mengerjakan pekerjaan rumah saya."},{"jp":"彼はまだ来ないです。","romaji":"Kare wa mada konai desu.","en":"He hasn't come yet.","id":"Dia belum datang."},{"jp":"映画はまだ始まっていないです。","romaji":"Eiga wa mada hajimatte inai desu.","en":"The movie hasn't started yet.","id":"Filmnya belum dimulai."},{"jp":"私たちはまだ夕食を食べていないです。","romaji":"Watashitachi wa mada yuushoku o tabete inai desu.","en":"We haven't eaten dinner yet.","id":"Kami belum makan malam."}]},{"pattern":"まだ～ません","meaning":"Expresses that something has not happened or been done yet (polite form).","meaningId":"Menyatakan sesuatu yang belum terjadi atau telah dilakukan (bentuk sopan).","formation":"まだ + Verb-ます form (negative)","formationId":"まだ + Bentuk Kata Kerja-ます (negatif)","examples":[{"jp":"昼ご飯をまだ食べていません。","romaji":"Hirugohan o mada tabete imasen.","en":"I have not eaten lunch yet.","id":"Saya belum makan siang."},{"jp":"宿題がまだ終わっていません。","romaji":"Shukudai ga mada owatte imasen.","en":"I have not finished my homework yet.","id":"Saya belum menyelesaikan pekerjaan rumah saya."},{"jp":"東京にはまだ行ったことがありません。","romaji":"Toukyou ni wa mada itta koto ga arimasen.","en":"I have not been to Tokyo yet.","id":"Saya belum pernah ke Tokyo."},{"jp":"彼はまだ来ていません。","romaji":"Kare wa mada kite imasen.","en":"He hasn't come yet.","id":"Dia belum datang."}]},{"pattern":"もう～","meaning":"Expresses 'already', 'anymore', or 'soon'.","meaningId":"Menyatakan 'sudah', 'lagi', atau 'segera'.","formation":"もう + Verb / もう + Adjective / もう + Noun","formationId":"もう + Kata Kerja / もう + Kata Sifat / もう + Kata Benda","examples":[{"jp":"もう昼ごはんを食べました。","romaji":"Mou hirugohan o tabemashita.","en":"I already ate lunch.","id":"Saya sudah makan siang."},{"jp":"もうここでは働かない。","romaji":"Mou koko de wa hatarakanai.","en":"I won't work here anymore.","id":"Saya tidak akan bekerja di sini lagi."},{"jp":"もうすぐ夏休みですね。","romaji":"Mou sugu natsuyasumi desu ne.","en":"Summer vacation is coming soon, isn't it?","id":"Liburan musim panas akan segera tiba, bukan?"},{"jp":"もう十分です。","romaji":"Mou juubun desu.","en":"It's already enough.","id":"Itu sudah cukup."}]},{"pattern":"もうすぐ〜","meaning":"Express an action or event happening soon: 'soon', 'in a short while', 'almost'.","meaningId":"Ekspresikan suatu tindakan atau peristiwa yang akan segera terjadi: 'segera', 'sebentar lagi', 'hampir'.","formation":"もうすぐ + Verb (~ます form or 〜る form)","formationId":"もうすぐ + Kata Kerja (bentuk ~ます atau bentuk 〜る)","examples":[{"jp":"もうすぐ春が来ます。","romaji":"Mou sugu haru ga kimasu.","en":"Spring is coming soon.","id":"Musim semi akan segera tiba."},{"jp":"もうすぐ彼女の誕生日です。","romaji":"Mou sugu kanojo no tanjoubi desu.","en":"Her birthday is coming up soon.","id":"Ulang tahunnya akan segera tiba."},{"jp":"もうすぐ試験が終わる。","romaji":"Mou sugu shiken ga owaru.","en":"The exam will be over soon.","id":"Ujian akan segera berakhir."},{"jp":"もうすぐ雨が止むでしょう。","romaji":"Mou sugu ame ga yamu deshou.","en":"The rain will likely stop soon.","id":"Hujan kemungkinan besar akan segera berhenti."}]},{"pattern":"もっと〜 (motto〜)","meaning":"Expresses 'more' or 'even more' when describing a quantity, frequency, or degree.","meaningId":"Menyatakan 'lebih' atau 'bahkan lebih' ketika mendeskripsikan kuantitas, frekuensi, atau derajat.","formation":"もっと + Verb / い-Adjective / な-Adjective","formationId":"もっと + Kata Kerja / い-Kata Sifat / な-Kata Sifat","examples":[{"jp":"もっと勉強しなければなりません。","romaji":"Motto benkyou shinakereba narimasen.","en":"I have to study more.","id":"Saya harus belajar lebih banyak."},{"jp":"このかばんをもっと大きいサイズに変えたいです。","romaji":"Kono kaban o motto ookii saizu ni kaetai desu.","en":"I want to change this bag to a larger size.","id":"Saya ingin mengganti tas ini ke ukuran yang lebih besar."},{"jp":"もっと静かな場所で働きたいです。","romaji":"Motto shizuka na basho de hatarakitai desu.","en":"I want to work in a quieter place.","id":"Saya ingin bekerja di tempat yang lebih tenang."},{"jp":"彼女はもっと上手になりたいと思っています。","romaji":"Kanojo wa motto jouzu ni naritai to omotte imasu.","en":"She wants to become even better.","id":"Dia ingin menjadi lebih baik lagi."}]},{"pattern":"よく～","meaning":"Often used to express 'doing something well' or 'often'.","meaningId":"Sering digunakan untuk menyatakan 'melakukan sesuatu dengan baik' atau 'sering'.","formation":"よく + Verb-casual","formationId":"よく + Kata Kerja-santai","examples":[{"jp":"彼はよく勉強します。","romaji":"Kare wa yoku benkyou shimasu.","en":"He studies often.","id":"Dia sering belajar."},{"jp":"彼女はよく料理を作ります。","romaji":"Kanojo wa yoku ryouri o tsukurimasu.","en":"She often cooks.","id":"Dia sering memasak."},{"jp":"昔の友達とよく遊んでいました。","romaji":"Mukashi no tomodachi to yoku asonde imashita.","en":"I used to play a lot with my old friends.","id":"Dulu aku sering bermain dengan teman-teman lamaku."},{"jp":"よくできました！","romaji":"Yoku dekimashita!","en":"Well done!","id":"Bagus sekali!"}]},{"pattern":"～（場所）に～があります (〜basho ni 〜 ga arimasu)","meaning":"Express the existence or presence of something in a place.","meaningId":"Mengungkapkan keberadaan atau kehadiran sesuatu di suatu tempat.","formation":"Place + に + Object/Thing + が + あります","formationId":"Tempat + に + Benda/Benda + が + あります","examples":[{"jp":"図書館にたくさんの本があります。","romaji":"Toshokan ni takusan no hon ga arimasu.","en":"There are many books in the library.","id":"Ada banyak buku di perpustakaan."},{"jp":"公園に池があります。","romaji":"Kouen ni ike ga arimasu.","en":"There is a pond in the park.","id":"Ada sebuah kolam di taman."},{"jp":"駅の前にコンビニがあります。","romaji":"Eki no mae ni konbini ga arimasu.","en":"There is a convenience store in front of the station.","id":"Ada toko serba ada di depan stasiun."},{"jp":"山の上に神社があります。","romaji":"Yama no ue ni jinja ga arimasu.","en":"There is a shrine on top of the mountain.","id":"Ada sebuah kuil di puncak gunung."}]}]
